import{_ as t,o,c as r,ag as a}from"./chunks/framework.BIas3y6W.js";const h=JSON.parse('{"title":"Tool changes since 25 September 2026: row-by-row verification of TOOLS.md (checked 21 October 2026)","description":"","frontmatter":{"source":"research/notes/2026-10/tool-changes-since-september.md"},"headers":[],"relativePath":"research/notes/2026-10/tool-changes-since-september.md","filePath":"research/notes/2026-10/tool-changes-since-september.md"}'),n={name:"research/notes/2026-10/tool-changes-since-september.md"};function s(i,e,d,l,c,u){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="tool-changes-since-25-september-2026-row-by-row-verification-of-toolsmd-checked-21-october-2026" tabindex="-1">Tool changes since 25 September 2026: row-by-row verification of TOOLS.md (checked 21 October 2026) <a class="header-anchor" href="#tool-changes-since-25-september-2026-row-by-row-verification-of-toolsmd-checked-21-october-2026" aria-label="Permalink to &quot;Tool changes since 25 September 2026: row-by-row verification of TOOLS.md (checked 21 October 2026)&quot;">​</a></h1><p>How to read these notes</p><ul><li><strong>Scope:</strong> every row of <code>TOOLS.md</code> (dated 25 Sep 2026), checked against official pages and the baseline notes in <code>research/notes/tools-chat-and-app-builders.md</code> and <code>research/notes/tools-ide-cli-apis-hosting.md</code>.</li><li><strong>Date checked:</strong> every fact was checked on <strong>2026-10-21</strong> unless a row gives another date. A date in brackets after a page, for example (upd. 2026-10-20), is the page&#39;s own &quot;last updated&quot; stamp.</li><li><strong>Source labels:</strong><ul><li><strong>[official]:</strong> the vendor&#39;s own page, opened in full.</li><li><strong>[official, snippet]:</strong> a vendor page seen only in a search summary, usually because it returned 403.</li><li><strong>[3rd-party]:</strong> press, a blog or a tracker, opened in full.</li><li><strong>[3rd-party, snippet]:</strong> press, a blog or a tracker seen only in a search summary.</li><li><strong>[GitHub API]:</strong> read from api.github.com.</li><li>Pricing pages were read through a summarizing fetch tool. Re-check the exact numbers by hand before printing them.</li></ul></li><li><strong>Status codes for each TOOLS.md claim:</strong><ul><li><strong>ACCURATE:</strong> still true.</li><li><strong>CHANGED:</strong> the claim is now wrong or incomplete. The row says what changed, when, and the source.</li><li><strong>PRECISION:</strong> not a change since September, but the current wording is looser than the sources support.</li><li><strong>UNVERIFIED:</strong> could not be re-checked on 21 Oct. The last known state is given.</li></ul></li></ul><hr><h2 id="1-chat-assistants-toolsmd-chat-assistants-weeks-13-what-changed-for-gemini-chatgpt-and-claude" tabindex="-1">1. Chat assistants (TOOLS.md &quot;Chat assistants&quot;, weeks 1–3): what changed for Gemini, ChatGPT and Claude? <a class="header-anchor" href="#1-chat-assistants-toolsmd-chat-assistants-weeks-13-what-changed-for-gemini-chatgpt-and-claude" aria-label="Permalink to &quot;1. Chat assistants (TOOLS.md &quot;Chat assistants&quot;, weeks 1–3): what changed for Gemini, ChatGPT and Claude?&quot;">​</a></h2><h3 id="takeaway" tabindex="-1">Takeaway <a class="header-anchor" href="#takeaway" aria-label="Permalink to &quot;Takeaway&quot;">​</a></h3><p><strong>The biggest change since September is Gemini Free.</strong> Since <strong>9 Oct 2026</strong> it defaults to the <strong>Flash-Lite</strong> model, where it used to default to Flash with some Pro. AI Plus lost Pro, and Pro access now needs AI Pro ($19.99), which also adds the new Gemini 4 Argon. Canvas and Gems are still listed as free.</p><p><strong>ChatGPT:</strong></p><ul><li>GPT-5.5 was due to retire from ChatGPT and Codex on 14 Oct 2026 (12:00 PDT). The official pricing page documents the date, but only third-party pieces confirm that it actually happened.</li><li>Free and Go users began getting <strong>GPT-6 Luna</strong> in the Chat tab from <strong>8 Oct</strong>, plus a new &quot;Intelligent UI&quot; that shows interactive components. It is not a code preview.</li></ul><p><strong>Claude:</strong> Claude Free moved to <strong>Sonnet 5.5</strong> (released 28 Sep). Prices, the 18+ rule and the training defaults are unchanged for all three assistants.</p><h3 id="cited-findings" tabindex="-1">Cited Findings <a class="header-anchor" href="#cited-findings" aria-label="Permalink to &quot;Cited Findings&quot;">​</a></h3><h4 id="row-by-row-verification-toolsmd--status" tabindex="-1">Row-by-row verification (TOOLS.md → status) <a class="header-anchor" href="#row-by-row-verification-toolsmd--status" aria-label="Permalink to &quot;Row-by-row verification (TOOLS.md → status)&quot;">​</a></h4><table tabindex="0"><thead><tr><th>TOOLS.md claim</th><th>Status</th><th>What the sources say (checked 2026-10-21)</th><th>Sources</th></tr></thead><tbody><tr><td><strong>Gemini — free tier:</strong> &quot;Fast Flash model, some access to the Pro model; limits not published&quot;</td><td><strong>CHANGED (9 Oct 2026)</strong></td><td><strong>Google&#39;s help page &quot;Changes to Gemini model access and limits&quot;:</strong><br>• &quot;Starting in October 2026, there will be changes to model availability for Gemini Apps when you use a personal account.&quot; The change applies on <strong>9 Oct</strong> for users without an AI plan; AI Plus users get an email with their date.<br>• &quot;Auto will be the default setting for users without a Google AI plan.&quot; Auto sends most prompts to Flash-Lite and some to Flash or Pro. With smart model selection off, &quot;chats for users without an AI plan will use Flash-Lite for all responses.&quot;<br>• Limits are compute-based and &quot;refresh every 5 hours until you reach your weekly limit&quot;. Free gets &quot;Standard limits&quot;; Plus 2x; Pro 4x; Ultra 5x or 20x of Pro. No numbers are given.<br><strong>The subscriptions page</strong> now lists Free as &quot;Access to our Flash-Lite model&quot;.<br><strong>A third-party report</strong> says Free chats are limited to a 32K-token context (128K on Plus, 1M on Pro).</td><td><a href="https://support.google.com/gemini/answer/17004136?hl=en" target="_blank" rel="noreferrer">Gemini Apps Help 17004136</a> [official]; <a href="https://gemini.google/subscriptions/" target="_blank" rel="noreferrer">gemini.google/subscriptions</a> [official]; <a href="https://www.creativeainews.com/articles/gemini-free-tier-flash-lite-only-oct-9-2026/" target="_blank" rel="noreferrer">Creative AI News</a> [3rd-party]</td></tr><tr><td><strong>Gemini — cheapest paid:</strong> &quot;Google AI Plus $4.99 · AI Pro $19.99&quot;</td><td><strong>ACCURATE (prices); CHANGED (what they include)</strong></td><td><strong>AI Plus ($4.99):</strong> &quot;Access to our Flash model&quot;. Pro is no longer listed.<br><strong>AI Pro ($19.99):</strong> &quot;Access to Gemini 4 Argon&quot; plus Pro and Flash, 4x limits, Jules with higher limits, and entry-level Antigravity.<br><strong>Gemini 4 Argon:</strong> announced 30 Sep. It went GA on <strong>13 Oct 2026</strong> on the paid Gemini API and for AI Pro/Ultra in the Gemini app.</td><td><a href="https://gemini.google/subscriptions/" target="_blank" rel="noreferrer">gemini.google/subscriptions</a> [official]; <a href="https://ai.google.dev/gemini-api/docs/changelog" target="_blank" rel="noreferrer">Gemini API changelog</a> [official] (<code>gemini-4-argon</code> GA Oct 13); <a href="https://dev.to/hassann/gemini-4-argon-is-out-5cpp" target="_blank" rel="noreferrer">DEV Community summary</a> [3rd-party, snippet]</td></tr><tr><td><strong>Gemini — coding features:</strong> &quot;Canvas runs HTML/JS previews in the chat; Gems&quot;</td><td><strong>ACCURATE (still listed free); UNVERIFIED (which model runs Canvas)</strong></td><td>Canvas and Gems are still under &quot;Free&quot; on the subscriptions page. Google has not said whether Canvas now runs on Flash-Lite.</td><td><a href="https://gemini.google/subscriptions/" target="_blank" rel="noreferrer">gemini.google/subscriptions</a> [official]; <a href="https://www.creativeainews.com/articles/gemini-free-tier-flash-lite-only-oct-9-2026/" target="_blank" rel="noreferrer">Creative AI News</a> [3rd-party]</td></tr><tr><td><strong>Gemini — age:</strong> &quot;13+&quot;</td><td><strong>ACCURATE (no change found)</strong></td><td>The help page mentions only that the earlier limit changes reached under-18 users on 24 Jul 2026. No new age rule was found.</td><td><a href="https://support.google.com/gemini/answer/17004136?hl=en" target="_blank" rel="noreferrer">Gemini Apps Help 17004136</a> [official]</td></tr><tr><td><strong>Gemini — training:</strong> &quot;Yes if &#39;Keep Activity&#39; is on; samples may be read by human reviewers&quot;</td><td><strong>ACCURATE (no change found)</strong></td><td>Searches found no Keep Activity change in Sep–Oct 2026. The last tracked notice changes were 30 Apr 2026 (personalization) and 1 Jul 2026 (third-party/MCP connections).</td><td><a href="https://conductatlas.com/platform/google-gemini/gemini-apps-privacy-notice/provision/CA-P-038253/keep-activity-setting-controls-chat-saving-and-ai-training/" target="_blank" rel="noreferrer">conductatlas tracker</a> [3rd-party, snippet]</td></tr><tr><td><strong>ChatGPT — free tier:</strong> &quot;Unlimited text chat on the small default model, with ads&quot;</td><td><strong>ACCURATE; model name updated</strong></td><td>The official pricing page lists Free and Go as &quot;GPT-6 Luna at Standard speed in the desktop app, subject to rollout&quot;.<br>OpenAI&#39;s release notes (quoted by third parties) say &quot;Free and Go use GPT-6 Luna&quot; in the <strong>Chat</strong> tab from <strong>8 Oct 2026</strong>, rolled out gradually. One OpenAI help article still said GPT-5.6 Luna.<br>Unlimited text chat has been in place since Aug 2026; no reversal was found.</td><td><a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">learn.chatgpt.com/docs/pricing</a> [official]; <a href="https://findskill.ai/blog/chatgpt-gpt-6-free-intelligent-ui-what-changed-2026/" target="_blank" rel="noreferrer">findskill.ai</a> [3rd-party, quotes the <a href="https://help.openai.com/en/articles/6825453-chatgpt-release-notes" target="_blank" rel="noreferrer">OpenAI release notes</a>, which returned 403]; <a href="https://letsdatascience.com/news/openai-brings-gpt-6-and-intelligent-ui-to-chatgpt-4f0d797c" target="_blank" rel="noreferrer">LetsDataScience</a> [3rd-party]</td></tr><tr><td><strong>ChatGPT — cheapest paid:</strong> &quot;Go $8 · Plus $20&quot;</td><td><strong>ACCURATE</strong></td><td><strong>Go:</strong> $8.<br><strong>Plus:</strong> $20, with Codex limits per 5 hours of GPT-6 Astra 5–45, GPT-6.1 Sol 15–160, GPT-6 Sol 15–150 and GPT-6 Luna 350–3,000.<br><strong>Pro:</strong> now $100, $200 or $500.<br><strong>New model:</strong> GPT-6.1 Sol (DevDay, 29 Sep 2026) is in Work and Codex for Plus and above, not in Chat, and not for Free or Go.</td><td><a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">learn.chatgpt.com/docs/pricing</a> [official]; <a href="https://www.unite.ai/openai-unveils-gpt-6.1-sol-at-devday-with-new-codex-and-chatgpt-tools/" target="_blank" rel="noreferrer">Unite.AI</a> [3rd-party, snippet]</td></tr><tr><td><strong>ChatGPT — coding features:</strong> &quot;In-chat code blocks; basic Codex access for quick tasks. Side-panel canvas reportedly removed May 2026&quot;</td><td><strong>ACCURATE + NEW feature</strong></td><td><strong>Codex on Free:</strong> positioned for &quot;quick coding tasks&quot; on the pricing page. OpenAI help says &quot;Codex is included across ChatGPT plans, including Free and Go&quot;, but <strong>Codex Cloud</strong> is not on Free or Go.<br><strong>New, &quot;Intelligent UI&quot;:</strong> from 7 Oct (paid) and 8 Oct (Free/Go), ChatGPT can &quot;combine text, visuals, and interactive elements&quot; such as calculators, bill splitters and games, built from OpenAI&#39;s component library. Nothing says it runs user HTML/JS, so it is <strong>not</strong> a Canvas/Artifacts equivalent. It has no separate quota; on web it can be turned down under Settings → Personalization → Layout and Visuals → Simple.<br><strong>Canvas:</strong> no sign that the side-panel canvas came back.</td><td><a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">learn.chatgpt.com/docs/pricing</a> [official]; <a href="https://help.openai.com/en/articles/11369540-codex" target="_blank" rel="noreferrer">OpenAI Help: Codex</a> [official, snippet]; <a href="https://findskill.ai/blog/chatgpt-gpt-6-free-intelligent-ui-what-changed-2026/" target="_blank" rel="noreferrer">findskill.ai</a> [3rd-party]</td></tr><tr><td><strong>ChatGPT — age:</strong> &quot;13+ with parental consent&quot;</td><td><strong>UNVERIFIED (403); no change found</strong></td><td>help.openai.com returned 403. The search found only the earlier age-prediction and teen-experience rollout, with no Oct 2026 change.</td><td><a href="https://help.openai.com/en/articles/12652064-chatgpt-for-teens" target="_blank" rel="noreferrer">OpenAI Help: ChatGPT for teens</a> [official, snippet]</td></tr><tr><td><strong>ChatGPT — training:</strong> &quot;Yes, opt out under Data Controls&quot;</td><td><strong>ACCURATE (no change found)</strong></td><td>The latest US privacy-policy revision found was dated 10 Sep 2026 (some copies say 18 May 2026). Training details are in a help article (403). No change to the opt-out was found.</td><td><a href="https://openai.com/policies/privacy-policy" target="_blank" rel="noreferrer">OpenAI privacy policy</a> [official, snippet]</td></tr><tr><td><strong>GPT-5.5 retirement (Known upcoming changes):</strong> &quot;14 Oct 2026: GPT-5.5 retires from ChatGPT and Codex&quot;</td><td><strong>ACCURATE (scheduled); event itself confirmed only by 3rd parties</strong></td><td>The official page says &quot;GPT-5.5 retires from Codex with ChatGPT sign-in on October 14, 2026, at noon PDT (19:00 UTC)&quot;. API and API-key Codex sessions are not affected.<br>Third parties add that ChatGPT, ChatGPT Work and Codex on all plans are covered and point Codex users to <code>gpt-5.6-sol</code>. A Towards AI post titled &quot;How to Still Use GPT-5.5 After ChatGPT Retired It&quot; implies it happened. No official post-event notice was fetched.</td><td><a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">learn.chatgpt.com/docs/pricing</a> [official]; <a href="https://letsdatascience.com/news/openai-retires-gpt-55-from-chatgpt-and-codex-1a6f69be" target="_blank" rel="noreferrer">LetsDataScience</a> [3rd-party]; <a href="https://pub.towardsai.net/how-to-still-use-gpt-5-5-after-chatgpt-retired-it-c2efba309ef3" target="_blank" rel="noreferrer">Towards AI</a> [3rd-party, snippet]</td></tr><tr><td><strong>Claude — free tier:</strong> &quot;Mid-size and small models; limits not published&quot;</td><td><strong>ACCURATE; model updated</strong></td><td><strong>Pricing page:</strong> Free has &quot;Sonnet and Haiku&quot;, with limits on a &quot;rolling five-hour session window&quot;.<br><strong>Sonnet 5.5:</strong> released <strong>28 Sep 2026</strong>. Simon Willison: &quot;now the model used for the free tier on claude.ai&quot;. Anthropic&#39;s announcement says Haiku 5.5 is coming &quot;in the coming weeks&quot;.<br><strong>Haiku 5.5:</strong> GitHub&#39;s changelog of 7 Oct 2026 is titled &quot;Claude Haiku 5.5 in GitHub Copilot&quot;, which implies it had shipped by then.</td><td><a href="https://claude.com/pricing" target="_blank" rel="noreferrer">claude.com/pricing</a> [official]; <a href="https://simonwillison.net/2026/Sep/28/claude-sonnet-5-5/" target="_blank" rel="noreferrer">Simon Willison 2026-09-28</a> [3rd-party, reputable]; <a href="https://www.anthropic.com/claude-sonnet-5-5" target="_blank" rel="noreferrer">Anthropic: Claude Sonnet 5.5</a> (linked, not fetched); <a href="https://github.blog/changelog/2026-10-07-claude-haiku-5-5-in-github-copilot" target="_blank" rel="noreferrer">GitHub changelog 2026-10-07</a> [official, title only]</td></tr><tr><td><strong>Claude — cheapest paid:</strong> &quot;Pro $20 ($17/mo annual) — includes Claude Code&quot;</td><td><strong>ACCURATE</strong></td><td>&quot;$17/month on annual billing ($200 up front); $20 if billed monthly&quot;; &quot;Claude Code included&quot;.<br><strong>Minor:</strong> Fable on Pro now shows &quot;Usage credits&quot; (it showed &quot;50% of weekly limits&quot; in Sept); &quot;50% of weekly limits&quot; now appears under Max.<br><strong>New banner:</strong> &quot;Claude Cowork is now just Claude&quot;, rolling out to Pro and Max.</td><td><a href="https://claude.com/pricing" target="_blank" rel="noreferrer">claude.com/pricing</a> [official]; <a href="https://www.shareduo.com/blog/what-is-claude-cowork" target="_blank" rel="noreferrer">ShareDuo</a> [3rd-party, snippet]</td></tr><tr><td><strong>Claude — coding features:</strong> &quot;Artifacts run HTML/JS/React previews in the chat&quot;</td><td><strong>ACCURATE</strong></td><td>Artifacts are listed on Free.</td><td><a href="https://claude.com/pricing" target="_blank" rel="noreferrer">claude.com/pricing</a> [official]</td></tr><tr><td><strong>Claude — age:</strong> &quot;18+&quot;</td><td><strong>ACCURATE</strong></td><td>&quot;We require all users to be at least 18 years old to create and use a Claude account&quot;. App-store age signals are used in some US states (article dated 16 Mar 2026).</td><td><a href="https://support.claude.com/en/articles/13117299-minimum-age-requirement-access-restriction" target="_blank" rel="noreferrer">Claude Help Center</a> [official]</td></tr><tr><td><strong>Claude — training:</strong> &quot;Yes (since Sept 2025), opt out in Privacy settings&quot;</td><td><strong>ACCURATE (no change found)</strong></td><td>No consumer-terms update after Sep 2025 surfaced in searches.</td><td><a href="https://www.anthropic.com/news/updates-to-our-consumer-terms" target="_blank" rel="noreferrer">Anthropic: Updates to Consumer Terms</a> [official, snippet]</td></tr></tbody></table><h3 id="inferences" tabindex="-1">Inferences <a class="header-anchor" href="#inferences" aria-label="Permalink to &quot;Inferences&quot;">​</a></h3><ul><li><strong>Weeks 1–3 primary:</strong> Gemini Canvas still works for $0, but the model behind it is now the smallest tier (Flash-Lite, a 32K context per a third party). Larger one-shot app builds in Canvas may get worse or hit context limits sooner. <ul><li>Claude Free (Sonnet 5.5, Artifacts) is now plausibly the strongest free in-chat preview tool, but only for students 18+.</li><li>Consider adding a line to TOOLS.md saying that Gemini Free now uses Flash-Lite. Have instructors re-test the week-1 Canvas demo before the cohort.</li></ul></li><li><strong>ChatGPT&#39;s &quot;Intelligent UI&quot;</strong> is not a substitute for Canvas or Artifacts in this course. It assembles OpenAI components and does not render student code. The TOOLS.md &quot;Not needed&quot; or fallback position for ChatGPT stays valid.</li><li><strong>Model names keep moving:</strong> GPT-6 Luna, GPT-6.1 Sol, Sonnet 5.5, Haiku 5.5 and Gemini 4 Argon all appeared within four weeks. This supports the TOOLS.md rule that model names appear only in this file.</li></ul><h3 id="gaps" tabindex="-1">Gaps <a class="header-anchor" href="#gaps" aria-label="Permalink to &quot;Gaps&quot;">​</a></h3><ul><li>Official OpenAI release-note and help pages (help.openai.com) returned 403. The GPT-6 Luna Free rollout date (8 Oct) and the GPT-5.5 retirement having happened rest on third-party reports that quote OpenAI.</li><li>Anthropic&#39;s own Sonnet 5.5 and Haiku 5.5 announcements were not fetched. Haiku 5.5&#39;s exact release date is unknown; it is inferred from GitHub&#39;s 7 Oct changelog title.</li><li><strong>Gemini Free:</strong><ul><li>The 32K context figure comes from a third party only.</li><li>Which model Canvas uses on Free is not stated by Google.</li><li>The help page&#39;s per-plan model table did not extract cleanly; the subscriptions page was used instead.</li></ul></li></ul><hr><h2 id="2-browser-app-builders-toolsmd-browser-app-builders-week-3-free-tier-changes-for-ai-studio-build-bolt-lovable-v0-replit-and-base44" tabindex="-1">2. Browser app builders (TOOLS.md &quot;Browser app builders&quot;, week 3): free-tier changes for AI Studio Build, Bolt, Lovable, v0, Replit and Base44 <a class="header-anchor" href="#2-browser-app-builders-toolsmd-browser-app-builders-week-3-free-tier-changes-for-ai-studio-build-bolt-lovable-v0-replit-and-base44" aria-label="Permalink to &quot;2. Browser app builders (TOOLS.md &quot;Browser app builders&quot;, week 3): free-tier changes for AI Studio Build, Bolt, Lovable, v0, Replit and Base44&quot;">​</a></h2><h3 id="takeaway-1" tabindex="-1">Takeaway <a class="header-anchor" href="#takeaway-1" aria-label="Permalink to &quot;Takeaway&quot;">​</a></h3><p><strong>Two builders cut their free tiers:</strong></p><ul><li><strong>v0:</strong> new sign-ups now get a <strong>one-time $5</strong>, not $5/month (around 4–5 Oct 2026). Existing Free users keep $5/month. The 7 messages/day cap is unchanged.</li><li><strong>Replit:</strong> the <strong>free Starter card was removed from replit.com/pricing</strong> around 10–11 Sep 2026. Replit&#39;s docs still describe Starter, and its old &quot;Lite&quot; experience is now called &quot;Free Mode&quot;.</li></ul><p><strong>No change:</strong></p><ul><li><strong>Lovable:</strong> still says its current chat pricing &quot;applies through October 31, 2026&quot;. No replacement was published as of 21 Oct.</li><li><strong>Bolt Free, Base44 Free and Google AI Studio Build:</strong> unchanged. Bolt Pro now shows $18/mo billed annually.</li></ul><h3 id="cited-findings-1" tabindex="-1">Cited Findings <a class="header-anchor" href="#cited-findings-1" aria-label="Permalink to &quot;Cited Findings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>TOOLS.md claim</th><th>Status</th><th>What the sources say</th><th>Sources</th></tr></thead><tbody><tr><td><strong>Google AI Studio Build:</strong> &quot;Full-stack React + Node apps with a database and auth, two-way GitHub sync, no card to prototype&quot;; 18+; free-tier training and review except EEA/UK/CH; Cloud Run needs billing</td><td><strong>ACCURATE</strong></td><td><strong>Build mode doc (upd. 2026-10-20):</strong><br>• React + Node.js, Firestore and Firebase Auth &quot;provisioned automatically&quot;, two-way GitHub sync, Cloud Run deploy or ZIP export.<br>• &quot;When sharing, API calls count toward your usage limits&quot;; &quot;Pricing for Google Cloud Run may apply&quot;.<br>• New banner: &quot;Gemini 4 Argon is now available&quot;. Argon is <strong>not</strong> on the free API tier (see §4).<br>• Apps built before 14 May 2026 are auto-upgraded to server-side keys when next edited.<br><strong>Gemini API Terms (upd. 2026-04-28):</strong> still say &quot;You must be 18 years of age or older&quot; and keep the EEA/UK/CH clauses.</td><td><a href="https://ai.google.dev/gemini-api/docs/aistudio-build-mode" target="_blank" rel="noreferrer">AI Studio Build mode</a> [official]; <a href="https://ai.google.dev/gemini-api/terms" target="_blank" rel="noreferrer">Gemini API Terms</a> [official]</td></tr><tr><td><strong>Bolt:</strong> &quot;About 1M tokens/month (300K/day), hosting, private projects&quot;</td><td><strong>ACCURATE</strong></td><td><strong>Free:</strong> &quot;Free forever, no card required&quot;; 1M tokens/month, a 300K daily limit, hosting, and public and private projects. It shows Bolt branding and has no custom domain.<br><strong>Pro:</strong> now shown at <strong>$18/mo billed annually ($216/yr)</strong> with 10M tokens and rollover.</td><td><a href="https://bolt.new/pricing" target="_blank" rel="noreferrer">bolt.new/pricing</a> [official]</td></tr><tr><td><strong>Lovable:</strong> &quot;5 credits/day, capped at 30/month&quot;; &quot;Pricing changes 31 Oct 2026&quot;</td><td><strong>ACCURATE; no replacement announced</strong></td><td><strong>Free:</strong> &quot;5 per day, up to 30 per month&quot;, 20 Cloud credits, 4 AI credits and 1 connector credit a month, plus a small daily chat allowance.<br>The docs still say: &quot;The current chat pricing model, including the per-message price and the daily chat allowance, applies through October 31, 2026.&quot; Grants are a &quot;Temporary offering, subject to change&quot;.<br>No post-31-Oct pricing has been published. A third-party blog claims credits were unified into one balance in Aug 2026, which is not confirmed.</td><td><a href="https://docs.lovable.dev/introduction/plans-and-credits" target="_blank" rel="noreferrer">docs.lovable.dev plans &amp; credits</a> [official]; <a href="https://lovable.dev/pricing" target="_blank" rel="noreferrer">lovable.dev/pricing</a> [official]; <a href="https://www.rapidevelopers.com/md/lovable-issues/lovable-pricing-and-credits-explained" target="_blank" rel="noreferrer">RapidDevelopers</a> [3rd-party, snippet]</td></tr><tr><td><strong>v0:</strong> &quot;About $5 of credits, 7 messages/day&quot;</td><td><strong>CHANGED (around 4–5 Oct 2026)</strong></td><td><strong>v0 docs (lastUpdated 2026-10-21):</strong><br>• &quot;New users who sign up under the one-time Free credit offer receive $5 once per user.&quot;<br>• &quot;Existing Free users keep their $5 monthly allowance.&quot;<br>• Free keeps &quot;7 messages&quot; a day, GitHub sync and Vercel deploy.<br><strong>Paid:</strong> &quot;Premium&quot; at $20 is being sunset and closed to new users, so the cheapest plan for a new user is <strong>Plus at $30/user/month</strong>.<br><strong>Trackers:</strong> two third-party captures dated the change to 4–5 Oct 2026.</td><td><a href="https://v0.app/docs/pricing" target="_blank" rel="noreferrer">v0 docs: pricing</a> [official]; <a href="https://v0.app/pricing" target="_blank" rel="noreferrer">v0.app/pricing</a> [official]; <a href="https://www.usagepricing.com/blueprint/activity/v0-2026-10-05-free-credits-one-time" target="_blank" rel="noreferrer">UsagePricing capture 2026-10-05</a> [3rd-party, snippet]</td></tr><tr><td><strong>Replit (Starter):</strong> &quot;&#39;Lite&#39; builds; one published app that goes down after 30 days&quot;</td><td><strong>CHANGED / at risk</strong></td><td><strong>Docs (Starter page):</strong> &quot;daily credits for Agent usage, up to a monthly cap&quot;; Lite build only; one free published app whose link &quot;will automatically go down after 30 days&quot;.<br><strong>Free Mode doc:</strong> &quot;For Starter users, the former Lite experience is now Free Mode.&quot; Starter &quot;includes Free Mode with its existing limits&quot;. Free Mode does not cover video generation.<br><strong>Pricing page:</strong> shows only Core ($20, or $18 billed annually: &quot;Up to 30 hours of chat on Free Mode&quot;, &quot;Up to 60 projects on Free Mode&quot;), Pro and Enterprise. A third-party tracker logged the <strong>Starter card&#39;s removal between 10 and 11 Sep 2026</strong>. It is not confirmed whether new sign-ups still get Starter.</td><td><a href="https://docs.replit.com/billing/plans/starter-plan" target="_blank" rel="noreferrer">docs.replit.com Starter</a> [official]; <a href="https://docs.replit.com/billing/plans" target="_blank" rel="noreferrer">docs.replit.com plans</a> [official]; <a href="https://docs.replit.com/help/free-agent-mode" target="_blank" rel="noreferrer">Free Mode docs</a> [official]; <a href="https://replit.com/pricing" target="_blank" rel="noreferrer">replit.com/pricing</a> [official]; <a href="https://pricingsaas.com/companies/replit/diffs/2026D254" target="_blank" rel="noreferrer">PricingSaaS diff 2026-09-11</a> [3rd-party]</td></tr><tr><td><strong>Base44</strong> (in the key questions, not in TOOLS.md)</td><td><strong>ACCURATE (vs. baseline)</strong></td><td><strong>Free:</strong> 25 message credits and 100 integration credits a month, up to 5 apps, no daily cap shown.<br><strong>Starter:</strong> $16/mo billed annually.</td><td><a href="https://base44.com/pricing" target="_blank" rel="noreferrer">base44.com/pricing</a> [official]</td></tr><tr><td><strong>Stack table:</strong> paid step &quot;Only if a capstone outgrows free credits ($16–25/mo)&quot;</td><td><strong>ACCURATE (roughly)</strong></td><td>Base44 is $16 and Bolt $18 (both annual); Lovable Pro is $25 per the baseline. <strong>But</strong> v0&#39;s cheapest plan open to new users is now $30, so v0 falls outside the range.</td><td>Sources above</td></tr></tbody></table><h3 id="inferences-1" tabindex="-1">Inferences <a class="header-anchor" href="#inferences-1" aria-label="Permalink to &quot;Inferences&quot;">​</a></h3><ul><li>v0 is now a <strong>one-session sampler</strong> for new students: $5 once plus 7 messages a day. TOOLS.md&#39;s &quot;one session each&quot; framing for Lovable, v0 and Replit still fits, but the v0 row should say &quot;one-time&quot;.</li><li>Replit is the weakest fallback. If new accounts no longer get Starter, the &quot;one session&quot; sampler may need a card or may not exist. Instructors should test a fresh sign-up before the cohort.</li><li>Lovable&#39;s 31 Oct cliff is still unresolved. Re-check in the first week of November, before the course starts in early 2027.</li></ul><h3 id="gaps-1" tabindex="-1">Gaps <a class="header-anchor" href="#gaps-1" aria-label="Permalink to &quot;Gaps&quot;">​</a></h3><ul><li>Whether new Replit sign-ups still receive the Starter plan; no official Replit statement was found.</li><li>Lovable&#39;s post-31-Oct-2026 pricing (not announced as of 21 Oct).</li><li>The exact effective date of v0&#39;s one-time-credit change (third-party captures only).</li></ul><hr><h2 id="3-editor-and-agents-toolsmd-editor-and-agents-weeks-48-copilot-codespaces-antigravity-claude-code-codex-cli-opencode-aider-cline-kilo-code-cursor-and-devin" tabindex="-1">3. Editor and agents (TOOLS.md &quot;Editor and agents&quot;, weeks 4–8): Copilot, Codespaces, Antigravity, Claude Code, Codex CLI, OpenCode, Aider, Cline, Kilo Code, Cursor and Devin <a class="header-anchor" href="#3-editor-and-agents-toolsmd-editor-and-agents-weeks-48-copilot-codespaces-antigravity-claude-code-codex-cli-opencode-aider-cline-kilo-code-cursor-and-devin" aria-label="Permalink to &quot;3. Editor and agents (TOOLS.md &quot;Editor and agents&quot;, weeks 4–8): Copilot, Codespaces, Antigravity, Claude Code, Codex CLI, OpenCode, Aider, Cline, Kilo Code, Cursor and Devin&quot;">​</a></h2><h3 id="takeaway-2" tabindex="-1">Takeaway <a class="header-anchor" href="#takeaway-2" aria-label="Permalink to &quot;Takeaway&quot;">​</a></h3><p><strong>GitHub Copilot and Codespaces:</strong> the Free, Student and Pro plan contents and the Codespaces quota are <strong>unchanged</strong>. GitHub&#39;s October changelog covers models, CLI features and security, not plan limits.</p><p><strong>Antigravity&#39;s free plan shrank:</strong></p><ul><li>The models page now gives Free and Plus users only <strong>Gemini 3.8 Flash</strong> plus Claude Sonnet/Opus 4.6 and gpt-oss-120b.</li><li>Those three third-party models are marked &quot;<strong>will be removed on November 2, 2026</strong>&quot;, which leaves Free on Gemini only.</li><li>Gemini 3.1 Pro is no longer on Free.</li><li>Gemini 4 Argon and Claude 5.5 need <strong>paid, non-trial</strong> AI Pro.</li></ul><p><strong>Other agents:</strong></p><ul><li><strong>Claude Code</strong> is still not free, and <strong>Codex</strong> still gives Free users quick tasks.</li><li><strong>Cursor&#39;s</strong> plans were folded into SpaceX/xAI&#39;s &quot;X Subscription&quot; on 12 Oct 2026.</li><li><strong>Aider</strong> has had <strong>no release since 9 Aug 2025</strong> and no commits since 22 May 2026.</li></ul><h3 id="cited-findings-2" tabindex="-1">Cited Findings <a class="header-anchor" href="#cited-findings-2" aria-label="Permalink to &quot;Cited Findings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>TOOLS.md claim</th><th>Status</th><th>What the sources say</th><th>Sources</th></tr></thead><tbody><tr><td><strong>Copilot Free:</strong> &quot;2,000 completions/month; unpublished AI Credits; automatic model choice only; agent mode, MCP and Copilot CLI included&quot;</td><td><strong>ACCURATE</strong></td><td><strong>Plans table:</strong> Free has &quot;Limited to 2,000 per month&quot; completions, an AI-credit &quot;allowance&quot; with no stated amount, &quot;Auto model selection only&quot;, and Agent mode, MCP and Copilot CLI included. Cloud agent is not included. Code review is &quot;Review selection&quot; in VS Code only.<br><strong>Marketing page:</strong> &quot;Free plan supports CLI and agent mode&quot;.</td><td><a href="https://docs.github.com/en/copilot/get-started/plans" target="_blank" rel="noreferrer">GitHub Docs: plans</a> [official]; <a href="https://github.com/features/copilot/plans" target="_blank" rel="noreferrer">github.com/features/copilot/plans</a> [official]</td></tr><tr><td><strong>Copilot Free note:</strong> &quot;running out of credits stops chat/agent work until the month resets — no cheaper fallback model&quot;</td><td><strong>ACCURATE</strong></td><td>Credits reset &quot;00:00:00 UTC on the first day of each calendar month&quot; and don&#39;t roll over. When they run out, the options are upgrade, set a US-dollar budget (1 credit = $0.01; you must pay off prior usage) or wait for the reset. No fallback model is mentioned.</td><td><a href="https://docs.github.com/en/copilot/concepts/billing-and-usage/individuals/billing" target="_blank" rel="noreferrer">GitHub Docs: individual billing</a> [official]</td></tr><tr><td><strong>Copilot Pro:</strong> &quot;$10 (model choice, larger credit pool)&quot;</td><td><strong>ACCURATE</strong></td><td>Pro is $10 with 1,500 credits (1,000 base + 500 flex) and &quot;A selection of models&quot;.<br><strong>Note:</strong> Gemini 4 Argon (13 Oct) is for &quot;Copilot Pro+, Max, Business, and Enterprise&quot; only, not Pro.</td><td><a href="https://docs.github.com/en/copilot/get-started/plans" target="_blank" rel="noreferrer">GitHub Docs: plans</a> [official]; <a href="https://github.blog/changelog/2026-10-13-gemini-4-argon-in-github-copilot" target="_blank" rel="noreferrer">Changelog 2026-10-13</a> [official]</td></tr><tr><td><strong>Copilot Student:</strong> &quot;unlimited completions, 200 AI Credits/month, cloud agent&quot;</td><td><strong>PRECISION (200 not official)</strong></td><td><strong>Official docs:</strong> Student is free, with an &quot;allowance&quot; of AI credits (number not stated), Auto only, unlimited completions, the cloud agent &quot;excludes third-party agents&quot;, and code review included.<br><strong>200/month figure:</strong> third-party only (Layer3Labs, updated 1 Oct 2026).</td><td><a href="https://docs.github.com/en/copilot/get-started/plans" target="_blank" rel="noreferrer">GitHub Docs: plans</a> [official]; <a href="https://docs.github.com/en/copilot/concepts/billing-and-usage/individuals/billing" target="_blank" rel="noreferrer">GitHub Docs: billing</a> [official]; <a href="https://www.layer3labs.io/guides/ai-student-discounts" target="_blank" rel="noreferrer">Layer3Labs</a> [3rd-party]</td></tr><tr><td><strong>Copilot: new since 25 Sep</strong> (not in TOOLS.md)</td><td><strong>NEW</strong></td><td><strong>Local Ollama models in Copilot CLI:</strong> <code>/model</code> lists models from a running local Ollama instance (CLI <strong>1.0.94-0</strong>, 7 Oct). The model must support tool calling and streaming. Whether this uses AI credits, and which plans get it, is not stated.<br><strong>Other changelog items:</strong><br>• Local sandboxing GA (7 Oct).<br>• Computer use in Copilot CLI and app, public preview (1 Oct).<br>• Code review: API support and a new default effort level, &quot;Balanced&quot; (2 Oct).<br>• Secret scanning detectors for Lovable and Supabase keys (5 Oct); Anthropic keys blocked by default (13 Oct).<br><strong>No October changelog entry mentions</strong> Copilot Free/Student plans, AI Credits, Codespaces, Pages or Education.</td><td><a href="https://github.blog/changelog/2026-10-07-discover-local-models-in-github-copilot-cli" target="_blank" rel="noreferrer">Changelog 2026-10-07 local models</a> [official]; <a href="https://github.blog/changelog/month/10-2026/" target="_blank" rel="noreferrer">Changelog Oct 2026 pages 1–5</a> [official]; <a href="https://github.blog/changelog/2026-10-05-secret-scanning-adds-detectors-for-lovable-supabase-and-more" target="_blank" rel="noreferrer">secret scanning 2026-10-05</a> [official]</td></tr><tr><td><strong>Copilot training policy:</strong> opt-out at github.com → Settings → Copilot</td><td><strong>ACCURATE</strong></td><td>&quot;for Individual subscribers only&quot; GitHub may use interaction data to train; opt out at github.com/settings/copilot/features. Business and Enterprise data is not used. <strong>No student exemption</strong> is mentioned.</td><td><a href="https://github.com/features/copilot/plans" target="_blank" rel="noreferrer">github.com/features/copilot/plans</a> [official]</td></tr><tr><td><strong>Codespaces:</strong> &quot;120 core-hours/month on GitHub Free (about 60 h on the 2-core machine), 15 GB storage; blocked, not billed&quot;</td><td><strong>ACCURATE</strong></td><td>GitHub Free gets &quot;120 hours of compute time and 15 GB-month of storage&quot;, with an &quot;included usage multiplier&quot; equal to the machine&#39;s core count. That is the same as 120 core-hours, or 60 h on a 2-core machine. &quot;usage is blocked once you use up your quota&quot; when no payment method is set. Organizations get no free quota.</td><td><a href="https://docs.github.com/en/billing/concepts/product-billing/github-codespaces" target="_blank" rel="noreferrer">GitHub Docs: Codespaces billing</a> [official]</td></tr><tr><td><strong>Antigravity:</strong> &quot;Frontier models with weekly limits (numbers not published)&quot;</td><td><strong>CHANGED (models page; removal 2 Nov 2026)</strong></td><td><strong>Models page, &quot;Free &amp; Plus&quot; column:</strong><br>• Gemini 3.8 Flash ✓<br>• Claude Sonnet 4.6 ✓ and Claude Opus 4.6 ✓ (both *)<br>• GPT-OSS-120b ✓ (*)<br>• Gemini 3.7/3.6 Flash and <strong>3.1 Pro</strong> ✗ (Enterprise only)<br>• Gemini 4 Argon ✗; Claude Sonnet/Opus 5.5 ✗<br>(*) = &quot;Will be removed on November 2, 2026&quot;.<br>Gemini 4 Argon and Claude 5.5 are &quot;Available on Google AI Pro for non-trial subscriptions only&quot;.<br><strong>Plans page:</strong> quota &quot;refreshed weekly&quot;; AI Pro &quot;resets every five hours … until the weekly limit is reached&quot;; all plans get &quot;the CLI&quot;.<br><strong>Pricing page:</strong> &quot;basic weekly rate limits&quot;; no numbers.</td><td><a href="https://antigravity.google/docs/models" target="_blank" rel="noreferrer">Antigravity models</a> [official]; <a href="https://antigravity.google/docs/plans" target="_blank" rel="noreferrer">plans</a> [official]; <a href="https://antigravity.google/pricing" target="_blank" rel="noreferrer">pricing</a> [official]; <a href="https://smartscope.blog/en/blog/antigravity-claude-55-pro-trial-model-retirement-2026/" target="_blank" rel="noreferrer">SmartScope</a> [3rd-party]</td></tr><tr><td><strong>Antigravity:</strong> &quot;Google AI Pro $19.99&quot; (cheapest paid); &quot;18+&quot;</td><td><strong>ACCURATE</strong></td><td><strong>FAQ:</strong> &quot;Currently, Antigravity is unavailable to users under 18&quot;; personal Google accounts in approved countries only. Some models &quot;are not included in free trials&quot;.<br><strong>Pricing page:</strong> shows no Pro price; the Gemini subscriptions page lists AI Pro at $19.99.</td><td><a href="https://antigravity.google/docs/faq" target="_blank" rel="noreferrer">Antigravity FAQ</a> [official]; <a href="https://gemini.google/subscriptions/" target="_blank" rel="noreferrer">gemini.google/subscriptions</a> [official]</td></tr><tr><td><strong>Claude Code:</strong> &quot;Not free; Claude Pro $20&quot;</td><td><strong>ACCURATE</strong></td><td>Free: &quot;Claude Code: Not included&quot;. Pro: &quot;Claude Code included&quot;.</td><td><a href="https://claude.com/pricing" target="_blank" rel="noreferrer">claude.com/pricing</a> [official]</td></tr><tr><td><strong>OpenAI Codex CLI:</strong> &quot;Basic access on Free (quick tasks only); ChatGPT Plus $20&quot;</td><td><strong>ACCURATE</strong></td><td><strong>Pricing page:</strong> Free is &quot;quick coding tasks&quot; with no usage figures.<br><strong>Help:</strong> Codex is included on Free and Go; Codex Cloud is not.<br><strong>Community report:</strong> Free accounts get &quot;The &#39;gpt-5.6-sol&#39; model is not supported when using Codex with a ChatGPT account&quot;.<br><strong>Latest release:</strong> <code>rust-v0.163.0</code> (15 Oct 2026).</td><td><a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">learn.chatgpt.com/docs/pricing</a> [official]; <a href="https://help.openai.com/en/articles/11369540-codex" target="_blank" rel="noreferrer">OpenAI Help: Codex</a> [official, snippet]; <a href="https://community.openai.com/t/free-plan-codex-credits-but-gpt-5-6-sol-is-still-blocked-what-s-the-point-of-the-credits/1393469" target="_blank" rel="noreferrer">OpenAI Community</a> [snippet]; <a href="https://github.com/openai/codex/releases" target="_blank" rel="noreferrer">openai/codex releases</a> [GitHub API]</td></tr><tr><td><strong>OpenCode / Aider / Cline / Kilo Code:</strong> &quot;Free, open source; pay for the model you connect&quot;</td><td><strong>ACCURATE, with a maintenance warning for Aider</strong></td><td><strong>OpenCode:</strong> v1.19.3 (16 Oct 2026). The repo <code>sst/opencode</code> now redirects to <code>anomalyco/opencode</code>. The official Zen docs list $0 models such as Big Pickle, DeepSeek V4 Flash Free and Nemotron 3 Ultra Free, which &quot;may change over time&quot;.<br><strong>Cline:</strong> release desktop-v0.0.48 (17 Oct 2026).<br><strong>Kilo Code:</strong> v7.8.15 (19 Oct 2026); &quot;Auto Free&quot; routing still documented.<br><strong>Aider:</strong> latest release <strong>v0.86.0 on 9 Aug 2025</strong>; last commit <strong>22 May 2026</strong>. Not archived, but inactive for about 5 months.</td><td><a href="https://github.com/anomalyco/opencode/releases" target="_blank" rel="noreferrer">anomalyco/opencode releases</a>, <a href="https://github.com/cline/cline/releases" target="_blank" rel="noreferrer">cline/cline releases</a>, <a href="https://github.com/Kilo-Org/kilocode/releases" target="_blank" rel="noreferrer">Kilo-Org/kilocode releases</a>, <a href="https://github.com/Aider-AI/aider" target="_blank" rel="noreferrer">Aider-AI/aider</a> [GitHub API]; <a href="https://opencode.ai/docs/zen" target="_blank" rel="noreferrer">OpenCode Zen docs</a> [official, snippet]; <a href="https://kilo.ai/docs/getting-started/using-kilo-for-free" target="_blank" rel="noreferrer">Kilo: using Kilo for free</a> [official, snippet]</td></tr><tr><td><strong>Cursor</strong> (not in TOOLS.md tables; only &quot;Cursor&#39;s free student year closed 25 Jun 2026&quot;)</td><td><strong>CHANGED (12 Oct 2026)</strong></td><td><strong>cursor.com/pricing:</strong><br>• No longer shows &quot;Hobby&quot;. &quot;Free&quot; lists &quot;Limited agent requests&quot;, &quot;Limited Chat requests&quot;, and &quot;Post, reply, and follow&quot; (X features).<br>• Cheapest paid is <strong>Plus $8/month</strong>, a shared pool across Cursor and Grok, with the footnote &quot;Only Grok models are available on this plan&quot;.<br>• Allowances &quot;refresh weekly&quot;.<br><strong>Press:</strong> SpaceX/xAI launched &quot;The X Subscription&quot; bundling Grok, Cursor and X Premium at Plus $8, Premium $30, Super $100 and Ultra $200 on 12 Oct 2026.<br><strong>Ended offer:</strong> the student free year is still closed.</td><td><a href="https://cursor.com/pricing" target="_blank" rel="noreferrer">cursor.com/pricing</a> [official]; <a href="https://fourweekmba.com/ai-spacex-bundles-grok-cursor-and-x-premium-from-8-to-200/" target="_blank" rel="noreferrer">FourWeekMBA</a> [3rd-party, snippet]; <a href="https://mezha.ua/en/news/spacexsi-new-subscriptions-316115/" target="_blank" rel="noreferrer">Mezha</a> [3rd-party, snippet]; <a href="https://www.layer3labs.io/guides/ai-student-discounts" target="_blank" rel="noreferrer">Layer3Labs</a> [3rd-party]</td></tr><tr><td><strong>Devin Desktop (formerly Windsurf)</strong> (not in TOOLS.md)</td><td><strong>UNVERIFIED</strong></td><td>devin.ai/pricing returned <strong>404</strong>. Third parties still describe a free tier with unlimited Tab completions. The Pro SWE-2 perk was due to end 10 Oct 2026 (baseline).</td><td><a href="https://www.windowsmode.com/devin-desktop-for-windows/" target="_blank" rel="noreferrer">Windows Mode guide</a> [3rd-party, snippet]</td></tr></tbody></table><h3 id="inferences-2" tabindex="-1">Inferences <a class="header-anchor" href="#inferences-2" aria-label="Permalink to &quot;Inferences&quot;">​</a></h3><ul><li><strong>Copilot (primary for weeks 4–8):</strong> unchanged. The new local-Ollama option in Copilot CLI could become a credit-free fallback inside the same tool, if it really costs no credits. That needs a hands-on test because the docs don&#39;t say. It would not work inside a Codespace without extra setup (same caveat as the Ollama row).</li><li><strong>Antigravity after 2 Nov 2026</strong> is still a free 18+ fallback, but on <strong>Gemini 3.8 Flash only</strong>. &quot;Frontier models&quot; overstates it. <ul><li>Students on Google&#39;s free 12-month AI Pro offer may count as &quot;trial&quot; users and be excluded from Argon and Claude 5.5. That is unverified; see Gaps.</li></ul></li><li><strong>Aider is a weak fallback:</strong> no release in 14 months. OpenCode (released 16 Oct) is the safer open-source terminal fallback. Kilo and Cline are both active.</li><li><strong>Cursor:</strong> its Free tier now sits inside an X/Grok consumer bundle that includes social-network features. That is another reason not to use it in a beginner course.</li></ul><h3 id="gaps-2" tabindex="-1">Gaps <a class="header-anchor" href="#gaps-2" aria-label="Permalink to &quot;Gaps&quot;">​</a></h3><ul><li>Exact Copilot Free and Student AI-credit allowances (GitHub does not publish them).</li><li>Whether Copilot CLI with a local Ollama model uses AI credits, and which plans can use it.</li><li>Whether Google&#39;s free student AI Pro counts as a &quot;trial&quot; for Antigravity&#39;s &quot;non-trial subscriptions only&quot; models.</li><li>Devin Desktop&#39;s current free plan (pricing page 404).</li><li>Numeric Cursor Free limits.</li></ul><hr><h2 id="4-llm-apis-for-student-apps-toolsmd-llm-apis-weeks-58-gemini-api-groq-openrouter-cloudflare-workers-ai-and-ollama" tabindex="-1">4. LLM APIs for student apps (TOOLS.md &quot;LLM APIs&quot;, weeks 5–8): Gemini API, Groq, OpenRouter, Cloudflare Workers AI and Ollama <a class="header-anchor" href="#4-llm-apis-for-student-apps-toolsmd-llm-apis-weeks-58-gemini-api-groq-openrouter-cloudflare-workers-ai-and-ollama" aria-label="Permalink to &quot;4. LLM APIs for student apps (TOOLS.md &quot;LLM APIs&quot;, weeks 5–8): Gemini API, Groq, OpenRouter, Cloudflare Workers AI and Ollama&quot;">​</a></h2><h3 id="takeaway-3" tabindex="-1">Takeaway <a class="header-anchor" href="#takeaway-3" aria-label="Permalink to &quot;Takeaway&quot;">​</a></h3><p><strong>The rows are still accurate:</strong></p><ul><li><strong>Gemini API:</strong> the free tier still covers Flash-Lite models, the OpenAI-compatible base URL is unchanged, limits are still unpublished, and the terms are unchanged. But <code>gemini-3.5-flash</code> and <code>gemini-3.7-flash</code> were deprecated on 8 Oct (auto-routed to newer models). <code>gemini-3.1-flash-lite</code> has an earliest shutdown of <strong>7 May 2027</strong>; its replacement is <code>gemini-3.5-flash-lite</code>.</li><li><strong>Groq:</strong> the free tab is still 30 requests/min and 1,000/day on gpt-oss and Qwen3.8-27b.</li><li><strong>OpenRouter:</strong> still 50/day, or 1,000/day after $10 of credits.</li><li><strong>Cloudflare:</strong> still 10,000 Neurons/day.</li><li><strong>Ollama:</strong> shipped v0.40.8 on 21 Oct 2026.</li></ul><h3 id="cited-findings-3" tabindex="-1">Cited Findings <a class="header-anchor" href="#cited-findings-3" aria-label="Permalink to &quot;Cited Findings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>TOOLS.md claim</th><th>Status</th><th>What the sources say</th><th>Sources</th></tr></thead><tbody><tr><td><strong>Gemini API base URL:</strong> <code>https://generativelanguage.googleapis.com/v1beta/openai/</code></td><td><strong>ACCURATE</strong></td><td>Same base URL; example model <code>gemini-3.8-flash</code>; &quot;Support for the OpenAI libraries is still in beta&quot; (upd. 2026-10-14).</td><td><a href="https://ai.google.dev/gemini-api/docs/openai" target="_blank" rel="noreferrer">Gemini OpenAI compatibility</a> [official]</td></tr><tr><td><strong>Gemini API free limits:</strong> &quot;Not published. Third parties report ~500 requests/day on Flash-Lite and ~20/day on Flash&quot;</td><td><strong>ACCURATE (&quot;not published&quot;); UNVERIFIED (third-party numbers)</strong></td><td><strong>Rate-limits page (upd. 2026-10-15):</strong> numbers &quot;can be viewed in Google AI Studio&quot;; &quot;Specified rate limits are not guaranteed&quot;.<br><strong>Third parties:</strong> no Oct 2026 source repeated the 500/20 figures. One May 2026 guide gave very different Flash numbers. Treat the figures as stale.</td><td><a href="https://ai.google.dev/gemini-api/docs/rate-limits" target="_blank" rel="noreferrer">Gemini rate limits</a> [official]; <a href="https://apidog.com/blog/what-is-gemini-3-5-flash-lite/" target="_blank" rel="noreferrer">Apidog</a> [3rd-party, snippet]</td></tr><tr><td><strong>Free models (Flash-Lite recommended)</strong></td><td><strong>ACCURATE + updates</strong></td><td><strong>Pricing page (upd. 2026-10-19), &quot;Free of charge&quot;:</strong><br>• Flash-Lite: Gemini <strong>3.5 Flash-Lite</strong>, 3.1 Flash-Lite, 2.5 Flash-Lite<br>• Flash: 3.8 Flash, 3.6 Flash, 3 Flash Preview, 2.5 Flash<br>• Gemini 2.5 Pro and Gemma 4<br><strong>Not available free:</strong> 3.1 Pro Preview and <strong>Gemini 4 Argon</strong>.<br><strong>Changelog:</strong><br>• 8 Oct: <code>gemini-3.7-flash</code> deprecated (routed to <code>gemini-3.8-flash</code>); <code>gemini-3.5-flash</code> deprecated (routed to <code>gemini-3.6-flash</code>).<br>• 18 Sep: &quot;For any new projects, use our latest models: 3.5 Flash-Lite or 3.8 Flash&quot; (2.5 limited to prior users).<br><strong>Deprecations page:</strong> <code>gemini-3.1-flash-lite</code> shutdown <strong>7 May 2027</strong> (earliest possible), replaced by <code>gemini-3.5-flash-lite</code>.</td><td><a href="https://ai.google.dev/gemini-api/docs/pricing" target="_blank" rel="noreferrer">Gemini pricing</a> [official]; <a href="https://ai.google.dev/gemini-api/docs/changelog" target="_blank" rel="noreferrer">changelog</a> [official]; <a href="https://ai.google.dev/gemini-api/docs/deprecations" target="_blank" rel="noreferrer">deprecations</a> [official]</td></tr><tr><td><strong>Gemini API notes:</strong> &quot;18+. Free-tier data may be used for training and read by reviewers. Free tier may not serve EEA/UK/CH users&quot;</td><td><strong>ACCURATE</strong></td><td><strong>Terms (upd. 2026-04-28):</strong><br>• &quot;You must be 18 years of age or older to use the APIs&quot;.<br>• &quot;human reviewers may read, annotate, and process your API input and output&quot;.<br>• &quot;You may use only Paid Services when making API Clients available to users in the European Economic Area&quot; (also Switzerland and UK).<br><strong>Pricing page:</strong> free tier &quot;Used to improve our products: Yes&quot;.</td><td><a href="https://ai.google.dev/gemini-api/terms" target="_blank" rel="noreferrer">Gemini API Terms</a> [official]; <a href="https://ai.google.dev/gemini-api/docs/pricing" target="_blank" rel="noreferrer">pricing</a> [official]</td></tr><tr><td><strong>Groq:</strong> <code>https://api.groq.com/openai/v1</code>; &quot;30 requests/minute, 1,000/day on open models such as gpt-oss&quot;; &quot;No card. Does not retain inference data by default&quot;</td><td><strong>ACCURATE</strong></td><td><strong>Rate-limits page:</strong> has &quot;Free Plan Limits&quot; and &quot;Developer Plan Limits&quot; tabs. <code>openai/gpt-oss-120b</code>, <code>openai/gpt-oss-20b</code> and <code>qwen/qwen3.8-27b</code> show 30 RPM, 1K RPD, 8K TPM and 200K TPD.<br><strong>Deprecations:</strong> no entries after 21 Sep 2026.<br><strong>Data:</strong> &quot;By default, Groq does not retain customer data for inference requests&quot;. It may log for reliability or abuse for up to 30 days, with an opt-out in Data Controls.</td><td><a href="https://console.groq.com/docs/rate-limits" target="_blank" rel="noreferrer">Groq rate limits</a> [official]; <a href="https://console.groq.com/docs/deprecations" target="_blank" rel="noreferrer">deprecations</a> [official]; <a href="https://console.groq.com/docs/your-data" target="_blank" rel="noreferrer">your data</a> [official]</td></tr><tr><td><strong>OpenRouter:</strong> &quot;50 requests/day on <code>:free</code> models (more after a one-time $10 top-up)&quot;; &quot;Free-model providers may log prompts&quot;</td><td><strong>ACCURATE</strong></td><td>20 RPM. 50/day with less than 10 credits ever purchased, 1,000/day with at least 10. The tier is based on all-time purchases. No dates or changes shown.</td><td><a href="https://openrouter.ai/docs/api-reference/limits" target="_blank" rel="noreferrer">OpenRouter limits</a> [official]</td></tr><tr><td><strong>Cloudflare Workers AI:</strong> &quot;10,000 Neurons/day&quot;; needs an account ID</td><td><strong>ACCURATE + note</strong></td><td><strong>Pricing (upd. 2026-10-20):</strong> 10,000 Neurons/day on Free and Paid. Free cannot exceed it (&quot;further operations will fail with an error&quot;). Resets at 00:00 UTC.<br><strong>New:</strong> some models, e.g. <code>@cf/zai-org/glm-5.2</code> and <code>@cf/deepseek-ai/deepseek-v4-pro-0813</code>, &quot;require a paid billing method&quot;.</td><td><a href="https://developers.cloudflare.com/workers-ai/platform/pricing/" target="_blank" rel="noreferrer">Workers AI pricing</a> [official]</td></tr><tr><td><strong>Ollama (local):</strong> <code>http://localhost:11434/v1</code>; ~16 GB RAM</td><td><strong>ACCURATE (no change found)</strong></td><td>Latest release <strong>v0.40.8, published 2026-10-21</strong> (baseline: v0.34.4, 23 Sep). The endpoint was not re-checked; no change reported.</td><td><a href="https://github.com/ollama/ollama/releases" target="_blank" rel="noreferrer">ollama/ollama releases</a> [GitHub API]</td></tr></tbody></table><h3 id="inferences-3" tabindex="-1">Inferences <a class="header-anchor" href="#inferences-3" aria-label="Permalink to &quot;Inferences&quot;">​</a></h3><ul><li>The week-5 lab tells students to pick a model &quot;with <code>flash-lite</code> in its name&quot;. The safest current pick is <strong><code>gemini-3.5-flash-lite</code></strong>: <ul><li>It is Google&#39;s own recommendation for new projects.</li><li>It has no shutdown date.</li><li><code>gemini-3.1-flash-lite</code> may be retired from 7 May 2027, which is likely during or just after an early-2027 cohort.</li></ul></li><li>Gemini 4 Argon is paid-only on the API. Students will see it in AI Studio&#39;s UI but cannot use it on a free key.</li><li>The fallback chain Gemini → Groq → OpenRouter → Cloudflare → Ollama is unchanged and still valid.</li></ul><h3 id="gaps-3" tabindex="-1">Gaps <a class="header-anchor" href="#gaps-3" aria-label="Permalink to &quot;Gaps&quot;">​</a></h3><ul><li>Current free-tier RPD for Gemini Flash-Lite and Flash. Google publishes them only inside AI Studio, and no fresh third-party measurement was found.</li><li>Whether Groq&#39;s &quot;Free Plan Limits&quot; tab differs per model beyond the three LLMs checked.</li></ul><hr><h2 id="5-hosting-and-data-toolsmd-hosting-and-data-weeks-18-github-pages-vercel-hobby-cloudflare-workers-supabase-neon-and-turso" tabindex="-1">5. Hosting and data (TOOLS.md &quot;Hosting and data&quot;, weeks 1–8): GitHub Pages, Vercel Hobby, Cloudflare Workers, Supabase, Neon and Turso <a class="header-anchor" href="#5-hosting-and-data-toolsmd-hosting-and-data-weeks-18-github-pages-vercel-hobby-cloudflare-workers-supabase-neon-and-turso" aria-label="Permalink to &quot;5. Hosting and data (TOOLS.md &quot;Hosting and data&quot;, weeks 1–8): GitHub Pages, Vercel Hobby, Cloudflare Workers, Supabase, Neon and Turso&quot;">​</a></h2><h3 id="takeaway-4" tabindex="-1">Takeaway <a class="header-anchor" href="#takeaway-4" aria-label="Permalink to &quot;Takeaway&quot;">​</a></h3><p><strong>Vercel Hobby:</strong> plan limits are unchanged, and the <code>export default { fetch }</code> function format is still documented.</p><ul><li><strong>New since 16 Sep 2026</strong> (just before TOOLS.md was verified, but not in it): a <strong>10 GB deployment-storage cap</strong>. Hobby keeps the 3 latest production deployments plus the 3 latest of any kind; over the limit, older ones are deleted immediately and deploys can be blocked.</li><li><strong>Precision fix:</strong> Vercel staff describe the GitHub-org block as applying to <strong>private</strong> org repos only.</li></ul><p><strong>Supabase:</strong> the <strong>Data API grants change hits all existing projects on 30 Oct 2026</strong>. Existing tables keep their grants; new tables need explicit <code>grant</code>s. Legacy <code>anon</code>/<code>service_role</code> keys are being deprecated &quot;by the end of 2026&quot;. Pausing is still 7 days.</p><p><strong>Neon:</strong> Free storage has doubled to <strong>1 GB per project</strong>.</p><p><strong>Cloudflare Workers:</strong> unchanged.</p><h3 id="cited-findings-4" tabindex="-1">Cited Findings <a class="header-anchor" href="#cited-findings-4" aria-label="Permalink to &quot;Cited Findings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>TOOLS.md claim</th><th>Status</th><th>What the sources say</th><th>Sources</th></tr></thead><tbody><tr><td><strong>GitHub Pages:</strong> &quot;Static sites from public repos; non-commercial; public repos only on free accounts&quot;</td><td><strong>UNVERIFIED (no change found)</strong></td><td>No Pages entries in GitHub&#39;s October 2026 changelog (pages 1–5) or the late-September entries. Docs were not re-fetched.</td><td><a href="https://github.blog/changelog/month/10-2026/" target="_blank" rel="noreferrer">GitHub Changelog Oct 2026</a> [official]</td></tr><tr><td><strong>Vercel Hobby:</strong> &quot;Static sites + serverless functions from a personal repo; non-commercial&quot;</td><td><strong>ACCURATE</strong></td><td><strong>Hobby doc (upd. 2026-09-14):</strong> &quot;non-commercial, personal use only&quot;; 1M function invocations, 4 CPU-hrs Active CPU, 100 GB Fast Data Transfer, 200 projects, 100 deployments/day; over a limit &quot;you will have to wait until 30 days have passed&quot;.</td><td><a href="https://vercel.com/docs/plans/hobby" target="_blank" rel="noreferrer">Vercel Hobby</a> [official]</td></tr><tr><td><strong>Vercel Hobby:</strong> &quot;Cannot deploy repos owned by a GitHub organization (fork to your personal account)&quot;</td><td><strong>PRECISION</strong></td><td><strong>Official Git docs (upd. 2026-09-17):</strong> don&#39;t mention a Hobby rule. For org repos they say you must be an org Owner or a Member with repo access.<br><strong>Vercel staff on the community forum:</strong> &quot;You cannot deploy to a Hobby team from a <strong>private</strong> repository in a GitHub organization… Consider making the repository public or upgrading to Pro&quot;. Another staff reply says public org repos can deploy.</td><td><a href="https://vercel.com/docs/git/vercel-for-github" target="_blank" rel="noreferrer">Vercel for GitHub</a> [official]; <a href="https://community.vercel.com/t/unable-to-deploy-from-organizational-private-repository/16334" target="_blank" rel="noreferrer">Vercel Community thread</a> and <a href="https://community.vercel.com/t/why-cant-hobby-accounts-deploy-from-organizations/10015" target="_blank" rel="noreferrer">thread</a> [vendor forum, snippet]</td></tr><tr><td><strong>Vercel: deployment retention</strong> (not in TOOLS.md)</td><td><strong>NEW (16 Sep 2026)</strong></td><td>&quot;Hobby teams get 10GB of Deployment Storage.&quot; Each project keeps its 3 most recent production deployments and 3 most recent of any type. The current production deployment and aliased or active-branch deployments are protected. Over the limit, others are &quot;deleted immediately instead of after 30 days&quot;, and &quot;going over the limit can block you from deploying&quot;.</td><td><a href="https://vercel.com/changelog/hobby-projects-now-retain-fewer-deployments-to-free-up-storage" target="_blank" rel="noreferrer">Vercel changelog 2026-09-16</a> [official]</td></tr><tr><td><strong>Vercel Functions format</strong> <code>export default { fetch }</code> (starter code)</td><td><strong>ACCURATE</strong></td><td><strong>Node.js runtime doc (upd. 2026-08-11):</strong> recommends a &quot;shared API entry point … using the <code>fetch</code> Web Standard export&quot; with <code>export default { fetch(request) {...} }</code>. Named <code>GET</code>/<code>POST</code> exports and the <code>(req, res)</code> style are also documented. No deprecation is mentioned.</td><td><a href="https://vercel.com/docs/functions/runtimes/node-js" target="_blank" rel="noreferrer">Vercel Node.js runtime</a> [official]</td></tr><tr><td><strong>Cloudflare Workers:</strong> &quot;Static assets + functions; slightly more setup&quot;</td><td><strong>ACCURATE</strong></td><td><strong>Limits (upd. 2026-10-12):</strong> 100,000 requests/day (Error 1027 after that), 10 ms CPU per request, 100 Workers; static assets up to 20,000 files per version, 25 MiB each.</td><td><a href="https://developers.cloudflare.com/workers/platform/limits/" target="_blank" rel="noreferrer">Workers limits</a> [official]</td></tr><tr><td><strong>Supabase Free:</strong> &quot;2 projects, Postgres, auth; pauses after 1 week of inactivity — restore from the dashboard&quot;</td><td><strong>ACCURATE</strong></td><td>&quot;Supabase pauses Free Plan projects that show low activity over a 7-day period&quot;; resume from the dashboard. The page is inconsistent on the restore window: the body says 1 year, a heading says 90 days.</td><td><a href="https://supabase.com/docs/guides/platform/free-project-pausing" target="_blank" rel="noreferrer">Supabase: free project pausing</a> [official]</td></tr><tr><td><strong>Supabase Data API grants</strong> (course <code>setup.sql</code> and instructor notes rely on explicit <code>grant</code>s)</td><td><strong>ACCURATE (scheduled); date confirmed</strong></td><td><strong>Changelog #45329:</strong><br>• Opt-out from 28 Apr 2026; default for new projects from <strong>30 May 2026</strong>; applied to all existing projects on <strong>30 Oct 2026</strong>.<br>• New <code>public</code> tables no longer get implicit <code>select/insert/update/delete</code> for <code>anon</code>, <code>authenticated</code> and <code>service_role</code>. Without grants, &quot;PostgREST returns a permission-denied error&quot;.<br>• <strong>Unaffected:</strong> &quot;Existing tables, which keep their current grants&quot;; RLS policies; direct Postgres connections.<br>• Reminder emails were scheduled for 23 Sep and 23 Oct 2026.</td><td><a href="https://supabase.com/changelog/45329-breaking-change-tables-not-exposed-to-data-and-graphql-api-automatically" target="_blank" rel="noreferrer">Supabase changelog #45329</a> [official]</td></tr><tr><td><strong>Supabase keys:</strong> publishable (<code>sb_publishable_</code>) vs legacy <code>anon</code> (weeks 7–8 materials)</td><td><strong>ACCURATE + deadline</strong></td><td>&quot;Supabase is deprecating the <code>anon</code> and <code>service_role</code> keys by the end of 2026.&quot; Legacy keys stay valid until disabled under Settings &gt; API Keys. Publishable keys map to <code>anon</code>/<code>authenticated</code>; secret keys (<code>sb_secret_</code>) to <code>service_role</code>, which bypasses RLS. No exact day is given.</td><td><a href="https://supabase.com/docs/guides/api/api-keys" target="_blank" rel="noreferrer">Supabase API keys</a> [official]</td></tr><tr><td><strong>Supabase RLS defaults</strong> (week-7 instructor notes: Table Editor on, SQL off)</td><td><strong>ACCURATE (no change found)</strong></td><td><strong>Security retro (Jan 2026):</strong> &quot;for tables created via the dashboard, RLS is enabled by default&quot;.<br><strong>Docs:</strong> if you create a table in raw SQL or the SQL editor, &quot;remember to enable RLS yourself&quot;.</td><td><a href="https://supabase.com/blog/supabase-security-2025-retro" target="_blank" rel="noreferrer">Supabase security retro 2025</a> [official, snippet]; <a href="https://www.supabase.com/docs/guides/auth/row-level-security" target="_blank" rel="noreferrer">Supabase RLS docs</a> [official, snippet]</td></tr><tr><td><strong>Neon:</strong> &quot;Postgres database only, no auth&quot;</td><td><strong>ACCURATE + limit change</strong></td><td><strong>Free:</strong> 100 projects; 100 CU-hours per project; <strong>1 GB storage per project (20 GB total)</strong> (baseline: 0.5 GB); 5 GB egress; 10 branches; scale-to-zero after 5 minutes; &quot;The Free plan is permanent (not a trial)&quot;; no card. A third-party tracker dates the storage doubling to week 41 (early Oct 2026).</td><td><a href="https://neon.com/pricing" target="_blank" rel="noreferrer">neon.com/pricing</a> [official]; <a href="https://pricingsaas.com/companies/neon" target="_blank" rel="noreferrer">PricingSaaS Neon</a> [3rd-party, snippet]</td></tr><tr><td><strong>Turso:</strong> &quot;SQLite database only&quot;</td><td><strong>UNVERIFIED (official page not fetched)</strong></td><td>Third parties still list Free as 100 databases, 5 GB, 500M rows read and 10M written a month, with no recorded change.</td><td><a href="https://agentdeals.dev/vendor/turso" target="_blank" rel="noreferrer">AgentDeals: Turso</a> [3rd-party, snippet]</td></tr></tbody></table><h3 id="inferences-4" tabindex="-1">Inferences <a class="header-anchor" href="#inferences-4" aria-label="Permalink to &quot;Inferences&quot;">​</a></h3><ul><li><strong>Supabase 30 Oct:</strong> for students who reuse an existing project and create <strong>new</strong> tables after 30 Oct, the change matters even outside the RLS lab. Any table their AI agent creates with plain <code>create table</code> will return permission-denied until it is granted. <ul><li>The week-7 notes describe this only for &quot;very new projects&quot;. After 30 Oct it applies to every project.</li><li>Legacy <code>anon</code> JWTs (<code>eyJ…</code>) should not be taught as a working alternative into 2027.</li></ul></li><li><strong>Vercel&#39;s 10 GB cap and 3+3 retention</strong> affect students who deploy dozens of previews a week. Older preview URLs they linked in homework may disappear. Tell students not to rely on old preview URLs as evidence; use a screenshot or the production URL.</li></ul><h3 id="gaps-4" tabindex="-1">Gaps <a class="header-anchor" href="#gaps-4" aria-label="Permalink to &quot;Gaps&quot;">​</a></h3><ul><li>GitHub Pages docs and Turso&#39;s pricing page were not re-fetched.</li><li>No official Vercel docs page states the Hobby rule on private org repos; the evidence is staff replies on Vercel&#39;s community forum.</li><li>The exact day in late 2026 when Supabase will disable legacy keys.</li></ul><hr><h2 id="6-student-offers-toolsmd-student-offers-are-the-deadlines-still-right-and-are-there-new-offers" tabindex="-1">6. Student offers (TOOLS.md &quot;Student offers&quot;): are the deadlines still right, and are there new offers? <a class="header-anchor" href="#6-student-offers-toolsmd-student-offers-are-the-deadlines-still-right-and-are-there-new-offers" aria-label="Permalink to &quot;6. Student offers (TOOLS.md &quot;Student offers&quot;): are the deadlines still right, and are there new offers?&quot;">​</a></h2><h3 id="takeaway-5" tabindex="-1">Takeaway <a class="header-anchor" href="#takeaway-5" aria-label="Permalink to &quot;Takeaway&quot;">​</a></h3><p><strong>All four TOOLS.md offers stand as written:</strong></p><ul><li>Google AI Pro: redeem by 31 Dec 2026, auto-renews.</li><li>ChatGPT Plus 4 months: claim by 31 Oct 2026. Only third parties confirm this; the official page returns 403.</li><li>Azure for Students: $100, no card.</li><li>GitHub Education → Copilot Student.</li></ul><p><strong>One offer TOOLS.md misses:</strong> OpenAI&#39;s <strong>$100 of Codex credits for verified university students in the US and Canada</strong> (launched 18 Jul 2026). It works with a ChatGPT <strong>Free</strong> account.</p><p><strong>Side effect of the Gemini change:</strong> after 9 Oct, the international AI Plus student year gives Flash, not Pro.</p><h3 id="cited-findings-5" tabindex="-1">Cited Findings <a class="header-anchor" href="#cited-findings-5" aria-label="Permalink to &quot;Cited Findings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>TOOLS.md claim</th><th>Status</th><th>What the sources say</th><th>Sources</th></tr></thead><tbody><tr><td><strong>GitHub Education → Copilot Student + Codespaces benefits;</strong> &quot;Apply in week 0&quot;</td><td><strong>ACCURATE</strong></td><td>No October changelog entries about Education or the Student plan. Student plan contents: see §3. A third party says eligibility is re-checked monthly and requires age 13+.</td><td><a href="https://docs.github.com/en/copilot/get-started/plans" target="_blank" rel="noreferrer">GitHub Docs: plans</a> [official]; <a href="https://www.layer3labs.io/guides/ai-student-discounts" target="_blank" rel="noreferrer">Layer3Labs</a> [3rd-party]</td></tr><tr><td><strong>Google AI Pro free for 12 months:</strong> &quot;US college students 18+ (AI Plus in 140+ other markets); redeem by 31 Dec 2026; needs a payment method and auto-renews&quot;</td><td><strong>ACCURATE; one PRECISION note</strong></td><td><strong>Google&#39;s blog (19 Aug 2026):</strong><br>• &quot;Redeem until December 31, 2026.&quot;<br>• US gets AI Pro; 140+ markets get AI Plus. Excluded: US, Bolivia, Albania, Canada, Macau, Hong Kong, Tunisia.<br>• Valid payment required; AI Pro charges $19.99/month after the free year.<br><strong>18+:</strong> the blog does not itself state 18+; the baseline and a third party do.<br><strong>Since 9 Oct:</strong> AI Plus gives Flash, not Pro (see §1).</td><td><a href="https://blog.google/innovation-and-ai/products/gemini-app/student-offer-google-ai/" target="_blank" rel="noreferrer">Google blog</a> [official]; <a href="https://www.layer3labs.io/guides/ai-student-discounts" target="_blank" rel="noreferrer">Layer3Labs</a> [3rd-party]; <a href="https://gemini.google/subscriptions/" target="_blank" rel="noreferrer">gemini.google/subscriptions</a> [official]</td></tr><tr><td><strong>ChatGPT Plus free for 4 months:</strong> &quot;US college students; claim by 31 Oct 2026&quot;</td><td><strong>ACCURATE (3rd-party confirmation; official 403)</strong></td><td>Four free monthly billing periods; current US college students verified via SheerID; claim by 31 Oct 2026; renews at $20/mo. App Store or Google Play subscriptions are excluded, and cancelling forfeits the remaining promo months.</td><td><a href="https://help.openai.com/en/articles/20001493-chatgpt-back-to-school-offer-for-students" target="_blank" rel="noreferrer">OpenAI Help 20001493</a> [official, snippet, 403]; <a href="https://www.layer3labs.io/guides/ai-student-discounts" target="_blank" rel="noreferrer">Layer3Labs</a> [3rd-party]</td></tr><tr><td><strong>Azure for Students:</strong> &quot;$100 credit, no card&quot;</td><td><strong>ACCURATE</strong></td><td>&quot;$100 credit&quot; for 12 months, renewable while a student; &quot;No credit card required&quot;; &quot;Available only to full-time university students&quot;.</td><td><a href="https://azure.microsoft.com/en-us/free/students" target="_blank" rel="noreferrer">Azure for Students</a> [official]</td></tr><tr><td><strong>NEW offer: Codex credits for students</strong></td><td><strong>NEW (launched 18 Jul 2026; missing from TOOLS.md)</strong></td><td><strong>OpenAI help center (snippet):</strong><br>• Verified university students living in the US or Canada; one per student.<br>• Works on ChatGPT Free, Go, Plus or Pro, including personal accounts, with SheerID school-email verification.<br>• Shows as 2,500 credits (= $100) and extends Codex usage beyond plan limits. Cloud use needs ChatGPT sign-in.<br><strong>Claim page:</strong> chatgpt.com/codex/students.<br><strong>Expiry:</strong> a third party says credits expire 12 months after the grant.</td><td><a href="https://help.openai.com/en/articles/20001147-codex-for-university-students" target="_blank" rel="noreferrer">OpenAI Help: Codex for university students</a> [official, snippet]; <a href="https://community.openai.com/t/100-free-codex-credits-for-university-students-in-the-us-and-canada/1387399" target="_blank" rel="noreferrer">OpenAI Community post 2026-07-18</a> [official forum]; <a href="https://www.layer3labs.io/guides/ai-student-discounts" target="_blank" rel="noreferrer">Layer3Labs</a> [3rd-party]</td></tr><tr><td><strong>Ended offers:</strong> &quot;Cursor&#39;s free student year (closed 25 Jun 2026), Perplexity&#39;s free year&quot;</td><td><strong>ACCURATE</strong></td><td>Cursor: &quot;No active student offer&quot;. Perplexity: Education Pro at $10/mo. Claude: no individual student offer; a third party says Claude for Education&#39;s campus programme is &quot;closed for Fall 2026&quot;.</td><td><a href="https://www.layer3labs.io/guides/ai-student-discounts" target="_blank" rel="noreferrer">Layer3Labs</a> [3rd-party]</td></tr></tbody></table><h3 id="inferences-5" tabindex="-1">Inferences <a class="header-anchor" href="#inferences-5" aria-label="Permalink to &quot;Inferences&quot;">​</a></h3><ul><li>For US and Canadian university students, the Codex credits give $100 of real terminal-agent capacity at $0, with no card or auto-renewal reported. It is a better optional step than &quot;ChatGPT Plus $20&quot; in weeks 6–8.</li><li>The ChatGPT Plus student offer closes before an early-2027 cohort starts. Remove it from the cohort-facing list after 31 Oct, or move it to &quot;ended&quot;.</li></ul><h3 id="gaps-5" tabindex="-1">Gaps <a class="header-anchor" href="#gaps-5" aria-label="Permalink to &quot;Gaps&quot;">​</a></h3><ul><li>The official OpenAI pages for both student offers returned 403. Terms come from search snippets and a third-party guide.</li><li>Whether the Codex student credits have a claim deadline (none published).</li><li>Whether Google&#39;s student AI Pro counts as a &quot;trial&quot; for Antigravity&#39;s paid-only models.</li></ul><hr><h2 id="7-do-not-use-and-privacy-settings-sections-still-accurate" tabindex="-1">7. &quot;Do not use&quot; and &quot;Privacy settings&quot; sections: still accurate? <a class="header-anchor" href="#7-do-not-use-and-privacy-settings-sections-still-accurate" aria-label="Permalink to &quot;7. &quot;Do not use&quot; and &quot;Privacy settings&quot; sections: still accurate?&quot;">​</a></h2><h3 id="takeaway-6" tabindex="-1">Takeaway <a class="header-anchor" href="#takeaway-6" aria-label="Permalink to &quot;Takeaway&quot;">​</a></h3><p><strong>Every &quot;Do not use&quot; row still holds:</strong></p><ul><li>Firebase Studio dates were re-confirmed on a page updated 20 Oct 2026.</li><li>GitHub Spark and GitHub Models stay retired.</li><li>ChatGPT&#39;s side-panel canvas is still gone; Intelligent UI is a different feature.</li></ul><p><strong>Privacy-setting paths:</strong> no changes were found for ChatGPT, Claude, Gemini, Copilot or AI Studio.</p><h3 id="cited-findings-6" tabindex="-1">Cited Findings <a class="header-anchor" href="#cited-findings-6" aria-label="Permalink to &quot;Cited Findings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>TOOLS.md claim</th><th>Status</th><th>What the sources say</th><th>Sources</th></tr></thead><tbody><tr><td><strong>Firebase Studio:</strong> &quot;New sign-ups closed 22 Jun 2026; shuts down 22 Mar 2027&quot;</td><td><strong>ACCURATE</strong></td><td>&quot;New workspace creation and user signup are disabled&quot; (22 Jun 2026). On 22 Mar 2027 &quot;all remaining data is permanently deleted&quot;. Recommended targets: Antigravity and AI Studio. Page upd. 2026-10-20.</td><td><a href="https://firebase.google.com/docs/studio/migrating-project" target="_blank" rel="noreferrer">Firebase Studio migration</a> [official]</td></tr><tr><td><strong>GitHub Spark:</strong> retired 31 Aug 2026. <strong>GitHub Models:</strong> retired 30 Jul 2026</td><td><strong>ACCURATE (no reversal found)</strong></td><td>No October changelog entries mention either product.</td><td><a href="https://github.blog/changelog/month/10-2026/" target="_blank" rel="noreferrer">GitHub Changelog Oct 2026</a> [official]</td></tr><tr><td><strong>Gemini CLI with a free Google login:</strong> &quot;Free login access ended 18 Jun 2026 (an API key still works, with low limits)&quot;</td><td><strong>ACCURATE</strong></td><td>Google&#39;s quota page (as indexed) says unpaid-tier and Google One users &quot;had Gemini CLI replaced by Antigravity CLI on June 18th, 2026&quot;, while still showing the old 1,000/day line. An unpaid API key gets 250 requests/day, Flash only.</td><td><a href="https://geminicli.com/docs/quota-and-pricing" target="_blank" rel="noreferrer">Gemini CLI quotas</a> [official, snippet]</td></tr><tr><td><strong>Roo Code, Continue; ChatGPT canvas; DeepSeek; Trae</strong></td><td><strong>ACCURATE (no change found)</strong></td><td>No new information in this pass. ChatGPT &quot;Intelligent UI&quot; (8 Oct) is a different feature and does not restore canvas (see §1).</td><td>See §1</td></tr><tr><td><strong>Privacy: ChatGPT</strong> &quot;Settings → Data Controls → Improve the model for everyone → off&quot;</td><td><strong>ACCURATE (no change found)</strong></td><td>The help page was not reachable (403).</td><td>—</td></tr><tr><td><strong>Privacy: Claude</strong> &quot;Settings → Privacy → Help improve Claude → off&quot;</td><td><strong>ACCURATE (no change found)</strong></td><td>—</td><td><a href="https://www.anthropic.com/news/updates-to-our-consumer-terms" target="_blank" rel="noreferrer">Anthropic consumer terms</a> [official, snippet]</td></tr><tr><td><strong>Privacy: Gemini</strong> &quot;Keep Activity → off (or temporary chats)&quot;</td><td><strong>ACCURATE</strong></td><td>See §1.</td><td>—</td></tr><tr><td><strong>Privacy: GitHub Copilot</strong> &quot;github.com → Settings → Copilot → turn off training&quot;</td><td><strong>ACCURATE</strong></td><td>The opt-out URL is github.com/settings/copilot/features.</td><td><a href="https://github.com/features/copilot/plans" target="_blank" rel="noreferrer">Copilot plans page</a> [official]</td></tr><tr><td><strong>Privacy: Google AI Studio / Gemini API</strong> &quot;No opt-out on the free tier&quot;</td><td><strong>ACCURATE</strong></td><td>Free tier &quot;Used to improve our products: Yes&quot;.</td><td><a href="https://ai.google.dev/gemini-api/docs/pricing" target="_blank" rel="noreferrer">Gemini pricing</a> [official]</td></tr></tbody></table><h3 id="inferences-6" tabindex="-1">Inferences <a class="header-anchor" href="#inferences-6" aria-label="Permalink to &quot;Inferences&quot;">​</a></h3><ul><li>Optionally add Cursor to &quot;Do not use&quot; (Free is now inside the X/Grok bundle with social features; see §3). Optionally list Aider as &quot;unmaintained since mid-2026&quot; next to Roo Code and Continue.</li></ul><h3 id="gaps-6" tabindex="-1">Gaps <a class="header-anchor" href="#gaps-6" aria-label="Permalink to &quot;Gaps&quot;">​</a></h3><ul><li>Direct confirmation of ChatGPT&#39;s Data Controls wording (403).</li></ul><hr><h2 id="8-proposed-edits-to-toolsmd-exact-old--new-wording" tabindex="-1">8. Proposed edits to TOOLS.md (exact old → new wording) <a class="header-anchor" href="#8-proposed-edits-to-toolsmd-exact-old--new-wording" aria-label="Permalink to &quot;8. Proposed edits to TOOLS.md (exact old → new wording)&quot;">​</a></h2><h3 id="takeaway-7" tabindex="-1">Takeaway <a class="header-anchor" href="#takeaway-7" aria-label="Permalink to &quot;Takeaway&quot;">​</a></h3><p>About 20 edits are needed:</p><ul><li><strong>Date bump:</strong> one.</li><li><strong>Factual changes:</strong> five (Gemini Free model, v0, Replit, Antigravity, Neon).</li><li><strong>New rows or notes:</strong> four (Codex student credits, Vercel storage cap, Supabase 30 Oct and legacy keys, Gemini model ID).</li><li><strong>Precision fixes:</strong> about four (Copilot Student credits, Vercel org repos, Aider, Gemini third-party limits).</li><li><strong>Updates to the &quot;Known upcoming changes&quot; table.</strong></li></ul><h3 id="cited-findings-each-edit-cites-the-evidence-row-above" tabindex="-1">Cited Findings (each edit cites the evidence row above) <a class="header-anchor" href="#cited-findings-each-edit-cites-the-evidence-row-above" aria-label="Permalink to &quot;Cited Findings (each edit cites the evidence row above)&quot;">​</a></h3><ol><li><p><strong>Header.</strong></p><ul><li>Old: <code>&gt; **Last verified: 25 September 2026.**</code></li><li>New: <code>&gt; **Last verified: 21 October 2026.**</code></li></ul></li><li><p><strong>Chat table header</strong> (and the LLM API table header).</p><ul><li>Old: <code>Free tier (as of 2026-09-25)</code> / <code>Free limits (as of 2026-09-25)</code></li><li>New: <code>Free tier (as of 2026-10-21)</code> / <code>Free limits (as of 2026-10-21)</code></li></ul></li><li><p><strong>Gemini row, &quot;Free tier&quot;</strong> (§1; <a href="https://support.google.com/gemini/answer/17004136?hl=en" target="_blank" rel="noreferrer">Gemini Help 17004136</a>, <a href="https://gemini.google/subscriptions/" target="_blank" rel="noreferrer">subscriptions</a>).</p><ul><li>Old: <code>Fast Flash model, some access to the Pro model; limits not published</code></li><li>New: <code>Flash-Lite model by default since 9 Oct 2026 (the Auto setting may send some prompts to Flash or Pro); limits refresh every 5 hours up to a weekly cap; numbers not published</code></li></ul></li><li><p><strong>Gemini row, &quot;Cheapest paid&quot;</strong> (§1).</p><ul><li>Old: <code>Google AI Plus $4.99 · AI Pro $19.99</code></li><li>New: <code>Google AI Plus $4.99 (adds Flash) · AI Pro $19.99 (adds Pro and Gemini 4 Argon)</code></li></ul></li><li><p><strong>ChatGPT row, &quot;Coding features&quot;</strong> (§1).</p><ul><li>Old: <code>In-chat code blocks; basic Codex access for quick tasks. The side-panel *canvas* was reportedly removed in May 2026</code></li><li>New: <code>In-chat code blocks; basic Codex access for quick tasks. The side-panel *canvas* was reportedly removed in May 2026. Since Oct 2026 &quot;Intelligent UI&quot; can show small interactive widgets (charts, forms, calculators), but it does not run your own code</code></li></ul></li><li><p><strong>Claude row, &quot;Free tier&quot;</strong> (optional; §1).</p><ul><li>Old: <code>Mid-size and small models; limits not published</code></li><li>New: <code>Mid-size and small models (Sonnet 5.5 since 28 Sep 2026); limits reset every 5 hours, numbers not published</code></li></ul></li><li><p><strong>v0 row</strong> (§2; <a href="https://v0.app/docs/pricing" target="_blank" rel="noreferrer">v0 docs</a>).</p><ul><li>Old: <code>| **v0** | About $5 of credits, 7 messages/day | — |</code></li><li>New: <code>| **v0** | New accounts: $5 of credits **once** (no monthly refill since Oct 2026); 7 messages/day | Older free accounts keep $5/month. Cheapest paid plan for new users is $30/mo |</code></li></ul></li><li><p><strong>Replit row</strong> (§2).</p><ul><li>Old: <code>| **Replit (Starter)** | &quot;Lite&quot; builds; one published app that goes down after 30 days | Keep your code in GitHub, not only in Replit |</code></li><li>New: <code>| **Replit (Starter)** | Agent in &quot;Free Mode&quot; (replaced &quot;Lite&quot;) with daily credits up to a monthly cap; one published app that goes down after 30 days | Starter no longer appears on replit.com/pricing (since Sep 2026); check that a new sign-up still gets it. Keep your code in GitHub, not only in Replit |</code></li></ul></li><li><p><strong>Lovable row, &quot;Notes&quot;</strong> (§2).</p><ul><li>Old: <code>Pricing changes 31 Oct 2026</code></li><li>New: <code>Current chat pricing ends 31 Oct 2026; no replacement announced as of 21 Oct. Re-check in November</code></li></ul></li><li><p><strong>Copilot Student row</strong> (§3).</p><ul><li>Old: <code>Free for verified students: unlimited completions, 200 AI Credits/month, cloud agent</code></li><li>New: <code>Free for verified students: unlimited completions, a monthly AI Credits allowance (GitHub doesn&#39;t publish the number; third parties report 200), cloud agent, code review</code></li></ul></li><li><p><strong>Antigravity row</strong> (§3; <a href="https://antigravity.google/docs/models" target="_blank" rel="noreferrer">models</a>).</p><ul><li>Old: <code>| **Google Antigravity** (IDE + </code>agy<code> CLI) | Frontier models with weekly limits (numbers not published) | Google AI Pro $19.99 | 18+. Good second opinion and fallback |</code></li><li>New: <code>| **Google Antigravity** (IDE + </code>agy<code> CLI) | Gemini 3.8 Flash with a weekly limit (numbers not published). Claude 4.6 and gpt-oss-120b leave the free plan on 2 Nov 2026 | Google AI Pro $19.99 (Gemini 4 Argon and Claude 5.5 need a paid, non-trial plan) | 18+. Good second opinion and fallback |</code></li></ul></li><li><p><strong>Open-source agents row and stack table</strong> (§3).</p><ul><li>Stack table, Terminal agent, Fallback 2: <code>OpenCode or Aider + free models</code> → <code>OpenCode + free models (Aider has had no release since Aug 2025)</code></li><li>Editor table notes: <code>Connect to Groq, OpenRouter free models or Ollama</code> → <code>Connect to Groq, OpenRouter free models or Ollama. OpenCode, Cline and Kilo Code all shipped releases in Oct 2026; Aider has not since Aug 2025</code></li></ul></li><li><p><strong>OpenAI Codex CLI row, notes</strong> (§3, §6).</p><ul><li>Old: <code>Optional for weeks 6–8</code></li><li>New: <code>Optional for weeks 6–8. University students in the US and Canada can claim $100 of free Codex credits (works with ChatGPT Free)</code></li></ul></li><li><p><strong>Gemini API row, &quot;Free limits&quot;</strong> (§4).</p><ul><li>Old: <code>Not published. Third parties report about 500 requests/day on Flash-Lite and about 20/day on Flash</code></li><li>New: <code>Not published (see AI Studio). Earlier third-party reports: about 500/day on Flash-Lite and about 20/day on Flash (not re-confirmed in Oct 2026). Use </code>gemini-3.5-flash-lite<code>; </code>gemini-3.1-flash-lite<code> may shut down from 7 May 2027</code></li></ul></li><li><p><strong>Cloudflare Workers AI row, notes</strong> (optional; §4).</p><ul><li>Old: <code>Needs a Cloudflare account ID</code></li><li>New: <code>Needs a Cloudflare account ID. Some newer models need a paid plan</code></li></ul></li><li><p><strong>Vercel Hobby row</strong> (§5).</p><ul><li>Old: <code>Non-commercial. **Cannot deploy repos owned by a GitHub organization** (fork to your personal account)</code></li><li>New: <code>Non-commercial. **Cannot deploy private repos owned by a GitHub organization** (make the repo public or fork it to your personal account). 10 GB deployment storage; old deployments are deleted when you go over</code></li></ul></li><li><p><strong>Supabase row</strong> (§5).</p><ul><li>Old: <code>**Pauses after 1 week of inactivity** — restore it from the dashboard</code></li><li>New: <code>**Pauses after 1 week of inactivity** — restore it from the dashboard. From 30 Oct 2026, new tables need explicit </code>grant<code>s before the API can see them. Use the publishable/secret keys; the legacy anon/service_role keys are deprecated by the end of 2026</code></li></ul></li><li><p><strong>Neon / Turso row</strong> (optional; §5).</p><ul><li>Old: <code>| **Neon / Turso** | Postgres / SQLite databases | Database only, no auth |</code></li><li>New: <code>| **Neon / Turso** | Postgres (1 GB per project on Neon Free) / SQLite databases | Database only, no auth |</code></li></ul></li><li><p><strong>Student offers table, new row</strong> (§6).</p><ul><li>Add: <code>| Codex credits for students | Verified university students in the US and Canada | $100 of Codex credits (2,500 credits); works with ChatGPT Free; one per student; no card |</code></li><li>Google row: after 31 Oct, change the ChatGPT Plus row to &quot;ended&quot;. Optionally, in the Google row, change <code>(AI Plus in 140+ other markets)</code> to <code>(AI Plus, which includes Flash but not Pro, in 140+ other markets)</code>.</li></ul></li><li><p><strong>&quot;Known upcoming changes&quot; table</strong> (§9).</p><ul><li>Mark <code>14 Oct 2026 | GPT-5.5 retires from ChatGPT and Codex</code> as done (or delete it).</li><li>Add the rows listed in §9 (30 Oct, 2 Nov, 16 Nov, end of 2026, 7 May 2027).</li></ul></li><li><p><strong>&quot;Do not use&quot; table</strong> (optional; §3, §7).</p><ul><li>Add: <code>| Cursor (Free) | Since 12 Oct 2026 bundled into the X/Grok &quot;X Subscription&quot;; the $8 plan is Grok-only; no student offer |</code></li></ul></li><li><p><strong>Footer.</strong></p><ul><li>Old: <code>Sources for every row: [research/landscape-report-2026-09.md](research/landscape-report-2026-09.md) and the notes in [research/notes/](research/notes/).</code></li><li>New: append <code>October 2026 re-check: research_notes/Vibe coding courses October 2026 update/tool_changes_since_september.md.</code></li></ul></li></ol><h3 id="inferences-7" tabindex="-1">Inferences <a class="header-anchor" href="#inferences-7" aria-label="Permalink to &quot;Inferences&quot;">​</a></h3><ul><li><strong>Other course files</strong> (not TOOLS.md) may need follow-up: <ul><li><code>weeks/13-data-and-access/instructor-notes.md</code> says the Data API grants issue affects &quot;very new projects&quot;. After 30 Oct 2026 it affects every project&#39;s new tables.</li><li><code>weeks/09-apis-and-secrets/lab.md</code> points at &quot;flash-lite&quot; generically, which still works. TOOLS.md should name <code>gemini-3.5-flash-lite</code> as the current suggestion.</li></ul></li><li><strong>Instructor pre-cohort checklist</strong> should add three checks: <ul><li>a fresh Replit sign-up;</li><li>Lovable&#39;s post-31-Oct pricing;</li><li>the Antigravity free model list after 2 Nov.</li></ul></li></ul><h3 id="gaps-7" tabindex="-1">Gaps <a class="header-anchor" href="#gaps-7" aria-label="Permalink to &quot;Gaps&quot;">​</a></h3><ul><li>Edits 6, 15, 18 and 21 are optional and depend on the course&#39;s policy for how much detail TOOLS.md carries.</li></ul><hr><h2 id="9-new-and-upcoming-change-dates-nov-2026--mid-2027-for-a-course-starting-in-early-2027" tabindex="-1">9. New and upcoming change dates (Nov 2026 – mid-2027) for a course starting in early 2027 <a class="header-anchor" href="#9-new-and-upcoming-change-dates-nov-2026--mid-2027-for-a-course-starting-in-early-2027" aria-label="Permalink to &quot;9. New and upcoming change dates (Nov 2026 – mid-2027) for a course starting in early 2027&quot;">​</a></h2><h3 id="takeaway-8" tabindex="-1">Takeaway <a class="header-anchor" href="#takeaway-8" aria-label="Permalink to &quot;Takeaway&quot;">​</a></h3><p><strong>Dates to plan around:</strong></p><ul><li><strong>Before the cohort:</strong> Supabase existing-project grants (30 Oct), Lovable pricing (31 Oct), ChatGPT Plus student offer (31 Oct), Antigravity free models (2 Nov), Copilot model deprecations (16 Nov), Google student offer (31 Dec), Supabase legacy keys (end of 2026).</li><li><strong>During or near the cohort:</strong> Firebase Studio shutdown (22 Mar 2027) and the earliest Gemini 3.1 Flash-Lite shutdown (7 May 2027).</li></ul><h3 id="cited-findings-7" tabindex="-1">Cited Findings <a class="header-anchor" href="#cited-findings-7" aria-label="Permalink to &quot;Cited Findings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Date</th><th>Change</th><th>Relevance</th><th>Source</th></tr></thead><tbody><tr><td><s>14 Oct 2026</s></td><td>GPT-5.5 retired from ChatGPT, Work and Codex (ChatGPT sign-in), 12:00 PDT; API unaffected</td><td>Done; remove from the table</td><td><a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">learn.chatgpt.com/docs/pricing</a> [official]; <a href="https://letsdatascience.com/news/openai-retires-gpt-55-from-chatgpt-and-codex-1a6f69be" target="_blank" rel="noreferrer">LetsDataScience</a> [3rd-party]</td></tr><tr><td>23 Oct 2026</td><td>Supabase&#39;s second reminder email before the grants change</td><td>Info</td><td><a href="https://supabase.com/changelog/45329-breaking-change-tables-not-exposed-to-data-and-graphql-api-automatically" target="_blank" rel="noreferrer">Supabase changelog #45329</a> [official]</td></tr><tr><td><strong>30 Oct 2026</strong></td><td>Supabase applies &quot;new tables need explicit grants&quot; to <strong>all existing projects</strong> (existing tables keep their grants)</td><td><strong>High:</strong> weeks 7–8 and the capstone</td><td><a href="https://supabase.com/changelog/45329-breaking-change-tables-not-exposed-to-data-and-graphql-api-automatically" target="_blank" rel="noreferrer">Supabase changelog #45329</a> [official]</td></tr><tr><td><strong>31 Oct 2026</strong></td><td>Lovable&#39;s current chat pricing ends (no replacement published as of 21 Oct); ChatGPT Plus student offer claim deadline</td><td>Medium</td><td><a href="https://docs.lovable.dev/introduction/plans-and-credits" target="_blank" rel="noreferrer">Lovable docs</a> [official]; <a href="https://help.openai.com/en/articles/20001493-chatgpt-back-to-school-offer-for-students" target="_blank" rel="noreferrer">OpenAI Help 20001493</a> [official, snippet]</td></tr><tr><td><strong>2 Nov 2026</strong></td><td>Antigravity removes Claude Sonnet 4.6, Claude Opus 4.6 and GPT-OSS-120b; Free &amp; Plus are left with Gemini 3.8 Flash</td><td><strong>High:</strong> the editor and terminal fallback layers</td><td><a href="https://antigravity.google/docs/models" target="_blank" rel="noreferrer">Antigravity models</a> [official]</td></tr><tr><td>16 Nov 2026</td><td>GitHub Copilot deprecates Claude Opus 4.8, Claude Opus 5 and GPT-5.6 Terra (replacements: Opus 5.5, GPT-6.1 Sol or GPT-6 Luna)</td><td>Low: Free and Student are Auto-only; affects Pro and above</td><td><a href="https://github.blog/changelog/2026-10-15-upcoming-deprecation-of-selected-github-copilot-models-in-mid-november" target="_blank" rel="noreferrer">GitHub Changelog 2026-10-15</a> [official]</td></tr><tr><td>17 Nov 2026</td><td>Gemini API shuts down several TTS and Live preview models (<code>gemini-3.1-flash-tts-preview</code>, <code>gemini-3.1-flash-live-preview</code>, …)</td><td>Low, unless a lab uses voice</td><td><a href="https://ai.google.dev/gemini-api/docs/deprecations" target="_blank" rel="noreferrer">Gemini deprecations</a> [official]</td></tr><tr><td>30 Nov → Dec 2026</td><td>Gemini 4 Argon API launch pricing ($2/$10 per M tokens) ends; rates double in December (paid tier only)</td><td>Low (not on the free tier)</td><td><a href="https://dev.to/hassann/gemini-4-argon-is-out-5cpp" target="_blank" rel="noreferrer">DEV Community</a> [3rd-party, snippet]</td></tr><tr><td><strong>31 Dec 2026</strong></td><td>Google AI Pro (US) and AI Plus (intl) student offer: last day to redeem</td><td>Medium: advise eligible students before the cohort starts</td><td><a href="https://blog.google/innovation-and-ai/products/gemini-app/student-offer-google-ai/" target="_blank" rel="noreferrer">Google blog</a> [official]</td></tr><tr><td><strong>&quot;By the end of 2026&quot;</strong> (no exact day)</td><td>Supabase deprecates the legacy <code>anon</code> / <code>service_role</code> keys</td><td><strong>High:</strong> teach only publishable and secret keys</td><td><a href="https://supabase.com/docs/guides/api/api-keys" target="_blank" rel="noreferrer">Supabase API keys</a> [official]</td></tr><tr><td>15 Mar 2027</td><td><code>gemini-2.5-flash-image</code> (Nano Banana) earliest shutdown</td><td>Low</td><td><a href="https://ai.google.dev/gemini-api/docs/deprecations" target="_blank" rel="noreferrer">Gemini deprecations</a> [official]</td></tr><tr><td><strong>22 Mar 2027</strong></td><td>Firebase Studio shuts down; data deleted</td><td>Already in &quot;Do not use&quot;</td><td><a href="https://firebase.google.com/docs/studio/migrating-project" target="_blank" rel="noreferrer">Firebase Studio migration</a> [official]</td></tr><tr><td><strong>7 May 2027</strong></td><td><code>gemini-3.1-flash-lite</code> earliest shutdown (replacement <code>gemini-3.5-flash-lite</code>)</td><td><strong>Medium:</strong> pick 3.5 Flash-Lite in the week-5 starter</td><td><a href="https://ai.google.dev/gemini-api/docs/deprecations" target="_blank" rel="noreferrer">Gemini deprecations</a> [official]</td></tr></tbody></table><h3 id="inferences-8" tabindex="-1">Inferences <a class="header-anchor" href="#inferences-8" aria-label="Permalink to &quot;Inferences&quot;">​</a></h3><ul><li><strong>Two dates fall before an early-2027 cohort and change what students see on day one:</strong> Antigravity&#39;s 2 Nov model removal, and Supabase&#39;s 30 Oct grants plus the end-of-2026 legacy keys. Re-verify both in the pre-cohort check.</li><li><strong>Volatility since 25 Sep:</strong> in four weeks, three free tiers shrank (Gemini app, v0 for new users, Antigravity&#39;s models) and one builder dropped its free card from its pricing page (Replit). Only one free tier grew (Neon storage). This is consistent with the baseline finding that free tiers are trending toward smaller defaults and &quot;credits with caps&quot;.</li></ul><h3 id="gaps-8" tabindex="-1">Gaps <a class="header-anchor" href="#gaps-8" aria-label="Permalink to &quot;Gaps&quot;">​</a></h3><ul><li>No announcements were found yet for Jan–Mar 2027 plan changes at GitHub Copilot, Vercel, Groq or OpenRouter. Absence of evidence is not evidence of no change.</li><li>Lovable&#39;s replacement pricing, and whether it takes effect on 1 Nov 2026, is unknown.</li></ul>',116)])])}const p=t(n,[["render",s]]);export{h as __pageData,p as default};
